{
  "steps": [
    {
      "id": "S1",
      "title": "Cell Culture",
      "instruction": "Grow neural stem cells (Cor3–1) in Complete media supplemented with necessary components including DMEM/HAM’S-F12, glucose, MEM-NEAA, penicillin, streptomycin, BSA, β-Mercapto-ethanol, B-27, and N2."
    },
    {
      "id": "S2",
      "title": "Medium Preparation",
      "instruction": "Before changing the medium or passaging the cells, add EGF, FGF, and Laminin to the required volume of Complete media."
    },
    {
      "id": "S3",
      "title": "Neuronal Differentiation - Priming",
      "instruction": "24 hours after seeding, transfer the cells to priming medium (Euromed-N) supplemented with B-27 without vitamin A, N2, and FGF for 3 days."
    },
    {
      "id": "S4",
      "title": "Neuronal Differentiation - Maturation",
      "instruction": "After priming, transfer the cells to differentiation medium (1:3 ratio DMEM/HAM’S-F12:Neurobasal) supplemented with B-27 without vitamin A, N2, FGF, BDNF, and Laminin for 3 days."
    },
    {
      "id": "S5",
      "title": "Medium Change",
      "instruction": "Change the differentiation medium every 3 days, reducing FGF concentration by half until it reaches zero, while maintaining BDNF at 30 ng/ml."
    },
    {
      "id": "S6",
      "title": "Transduction of CRE Recombinase",
      "instruction": "Transduce neural stem cells (Floxed-Huwe1-RYFP) with adenovirus CMV-CRE at a MOI of 100, using empty adenovirus as a control."
    },
    {
      "id": "S7",
      "title": "P19 Cell Maintenance",
      "instruction": "Maintain P19 cells in MEM-α supplemented with FBS, penicillin, and streptomycin."
    },
    {
      "id": "S8",
      "title": "P19 Cell Differentiation",
      "instruction": "Transfer P19 cells to Neurobasal medium supplemented with penicillin/streptomycin, B-27 without vitamin A, GlutaMAX, and Laminin for differentiation."
    },
    {
      "id": "S9",
      "title": "Transfection of P19 Cells",
      "instruction": "Transfect P19 cells at 80% confluence with Lipofectamine 2000 using a 1:2 ratio of DNA to Lipofectamine."
    },
    {
      "id": "S10",
      "title": "RNA Extraction",
      "instruction": "Extract total RNA from cells using the RNeasy kit."
    },
    {
      "id": "S11",
      "title": "cDNA Synthesis",
      "instruction": "Synthesize template cDNAs using the QuantiTect Reverse Transcription Kit."
    },
    {
      "id": "S12",
      "title": "qRT-PCR",
      "instruction": "Perform quantitative Real-Time PCR using QuantiFast SYBR Green Master Mix in a Lightcycler 480 PCR system, normalizing to the housekeeping gene EiF1α."
    },
    {
      "id": "S13",
      "title": "Western Blotting",
      "instruction": "Prepare total cell lysates using RIPA buffer, determine protein concentration, and perform SDS-PAGE followed by transfer to nitrocellulose membranes for immunoblotting."
    },
    {
      "id": "S14",
      "title": "Cellular Fractionation",
      "instruction": "Seed Cor3–1 and P19 cells, wash, and fractionate cells using E1 and E2 buffers to obtain cytoplasmic and nuclear fractions."
    },
    {
      "id": "S15",
      "title": "Agarose-TUBEs Pull Down",
      "instruction": "Use Agarose-TUBEs to pull down ubiquitylated proteins from cytoplasmic and chromatin fractions, followed by washing and elution for analysis."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Ethics Approval",
      "instruction": "Ensure that the use of human specimens is approved by the Ethics Reviewing Board of the University Hospital of Liege."
    },
    {
      "id": "S2",
      "title": "Tissue Selection",
      "instruction": "Obtain lung postmortem biopsy specimens from four COVID-19 patients and four non-COVID-19 controls, ensuring they are matched for age and sex."
    },
    {
      "id": "S3",
      "title": "Sample Preparation",
      "instruction": "Formalin-fix and paraffin-embed the selected lung tissues, then cut serial sections of 4 µm thickness for histological and immunofluorescence examination."
    },
    {
      "id": "S4",
      "title": "H&E Staining",
      "instruction": "Stain the tissue sections with H&E and digitize the whole slides using a Pannoramic 250 Flash III Scanner."
    },
    {
      "id": "S5",
      "title": "Antigen Retrieval",
      "instruction": "Deparaffinize and rehydrate the tissue sections, then boil them in 10-mM sodium carbonate buffer for 20 minutes for antigen retrieval."
    },
    {
      "id": "S6",
      "title": "Permeabilization",
      "instruction": "Permeabilize the lung sections using PBS containing 0.5% Triton X-100."
    },
    {
      "id": "S7",
      "title": "Blocking",
      "instruction": "Incubate the samples with a blocking buffer (PBS with 2% BSA and 2% donkey serum) for 1 hour at room temperature."
    },
    {
      "id": "S8",
      "title": "Primary Antibody Staining",
      "instruction": "Stain the samples with rabbit anti-human antibodies against citrullinated histone H3 and goat anti-human antibodies against MPO in blocking buffer for 1 hour at room temperature."
    },
    {
      "id": "S9",
      "title": "Secondary Antibody Staining",
      "instruction": "Wash the samples with PBS, then incubate with secondary donkey anti-rabbit IgG and donkey anti-goat IgG antibodies conjugated with fluorescent dyes in blocking buffer containing DAPI for 2 hours in the dark."
    },
    {
      "id": "S10",
      "title": "Mounting Samples",
      "instruction": "Mount the stained samples on glass slides using ProLong Antifade reagent and store them at room temperature in the dark overnight."
    },
    {
      "id": "S11",
      "title": "Fluorescence Microscopy",
      "instruction": "Analyze all samples using fluorescence microscopy with standard filter sets and acquire images on a Zeiss LSM 880 Airyscan Elyra S.1. confocal microscope."
    },
    {
      "id": "S12",
      "title": "NET Volume Quantification",
      "instruction": "Quantify the volume of NETs in lung tissue by analyzing six fields per patient using Imaris software for three-dimensional reconstruction."
    },
    {
      "id": "S13",
      "title": "Scanning for NET Areas",
      "instruction": "Scan entire lung sections using the Nanozoomer 2.0-HT system and manually screen for areas rich in structures staining double positive for Cit-H3 and MPO."
    },
    {
      "id": "S14",
      "title": "Statistical Analysis",
      "instruction": "Perform statistical analysis on the data using a nonparametric Mann–Whitney U test to determine significance."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Germinate seeds",
      "instruction": "Germinate four-week-old tomato seeds in vermiculite under controlled growth chamber conditions with a 16/8h light/dark cycle, temperature of 24/18 °C, light intensity of 200 μmol m–2 s–1, and 60% relative humidity."
    },
    {
      "id": "S2",
      "title": "Irrigate seedlings",
      "instruction": "Irrigate the seedlings twice a week with distilled water for the first three weeks."
    },
    {
      "id": "S3",
      "title": "Apply nutrient solutions",
      "instruction": "Irrigate seedlings with Hoagland solution for control plants or with modified Hoagland solutions lacking nitrogen for treatment groups, adding K2SO4 and CaSO4 to compensate for nutrient deficiencies."
    },
    {
      "id": "S4",
      "title": "Prepare PA biosynthesis inhibitors",
      "instruction": "Dissolve DFMA and DFMO in water to create an inhibitor solution containing 2mM DFMA and 5mM DFMO."
    },
    {
      "id": "S5",
      "title": "Treat plants with inhibitors",
      "instruction": "Apply the inhibitor solution directly to each pot during the week prior to Pst inoculation."
    },
    {
      "id": "S6",
      "title": "Foliar spray with Put",
      "instruction": "Treat 4-week-old plants with 0.5mM Put or mock solution using foliar sprays applied 48 hours before Pst infection."
    },
    {
      "id": "S7",
      "title": "Inoculate plants with Pst",
      "instruction": "Prepare a bacterial suspension of Pst at 5×10^5 cfu ml–1 and inoculate the third and fourth leaves by dipping them into the suspension."
    },
    {
      "id": "S8",
      "title": "Score disease rate",
      "instruction": "Assess the disease rate at 72 hours post-inoculation by determining the percentage of dark-brown spots on the leaf surface."
    },
    {
      "id": "S9",
      "title": "Collect leaf samples for analysis",
      "instruction": "Collect leaf samples at 3, 24, and 48 hours post-inoculation for molecular and hormonal analyses."
    },
    {
      "id": "S10",
      "title": "Measure biomass",
      "instruction": "Dry collected tomato plant tissues at 65 ºC for 2 days and weigh to determine dry weight as biomass."
    },
    {
      "id": "S11",
      "title": "Measure chlorophyll content",
      "instruction": "Use a chlorophyll meter to measure the chlorophyll level of leaves from 4-week-old tomato plants, taking three measurements per leaf."
    },
    {
      "id": "S12",
      "title": "Determine photosynthetic rate",
      "instruction": "Utilize an LCpro+ portable infrared gas analyser to measure the net photosynthetic rate on three mature leaves from each of the 10 replicate plants."
    },
    {
      "id": "S13",
      "title": "Perform DAB staining",
      "instruction": "Collect leaf samples for DAB staining at 3, 24, and 48 hours post-inoculation, and process them for quantification of staining intensities."
    },
    {
      "id": "S14",
      "title": "Extract RNA for qRT-PCR",
      "instruction": "Extract RNA from leaf tissue samples collected at 3 and 48 hours post-inoculation using the E.Z.N.A. Plant RNA Kit."
    },
    {
      "id": "S15",
      "title": "Analyze stomatal apertures",
      "instruction": "Inoculate the third and fourth leaves with Pst, prepare casts using dental resin, and analyze stomatal apertures using microscopy."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Prepare media",
      "instruction": "Prepare L broth (LB) and T broth (TB) by mixing the appropriate components. Add ampicillin and arabinose to the media at final concentrations of 100 µg/ml and 0.02% (wt/vol), respectively."
    },
    {
      "id": "S2",
      "title": "Replace fliG gene",
      "instruction": "Use the λ Red homologous recombination system to replace the fliG gene on the chromosome with a pHluorin(M153R)-fliG allele."
    },
    {
      "id": "S3",
      "title": "Grow Salmonella cells",
      "instruction": "Inoculate Salmonella cells in 5 ml of LB and grow with shaking at 30°C until the optical density at 600 nm (OD600) reaches approximately 1.0."
    },
    {
      "id": "S4",
      "title": "Wash cells",
      "instruction": "Perform low-speed centrifugation to pellet the cells, then wash the cell pellet twice with motility buffer (10 mM potassium phosphate, 0.1 mM EDTA, pH 7.0)."
    },
    {
      "id": "S5",
      "title": "Resuspend cells",
      "instruction": "Resuspend the washed cell pellets in motility buffer and incubate at 30°C for 1 hour."
    },
    {
      "id": "S6",
      "title": "Centrifuge cultures",
      "instruction": "Centrifuge the cultures again to separate the cell pellets from the culture supernatants."
    },
    {
      "id": "S7",
      "title": "Prepare samples for SDS-PAGE",
      "instruction": "Resuspend the cell pellets in SDS loading buffer. Precipitate proteins from the culture supernatants using 10% trichloroacetic acid, then suspend in Tris-SDS loading buffer and heat at 95°C for 5 minutes."
    },
    {
      "id": "S8",
      "title": "Perform SDS-PAGE",
      "instruction": "Run the samples on an SDS-PAGE gel and perform immunoblotting using polyclonal anti-FlgD and anti-FliC antibodies."
    },
    {
      "id": "S9",
      "title": "Purify pHluorin(M153R)",
      "instruction": "Purify pHluorin(M153R) from the soluble fractions of BL21(DE3)pLysS carrying pYVM007."
    },
    {
      "id": "S10",
      "title": "Purify pHluorin(M153R)-FliG",
      "instruction": "Purify pHluorin(M153R)-FliG-His using nickel-nitrilotriacetic acid (Ni-NTA) affinity chromatography from the soluble fractions of BL21(DE3)pLysS carrying pYVM013."
    },
    {
      "id": "S11",
      "title": "Set up fluorescence microscopy",
      "instruction": "Prepare a custom-built fluorescence microscope system with the appropriate optical components and excitation filters for observing Salmonella cells expressing pHluorin(M153R) variants."
    },
    {
      "id": "S12",
      "title": "Capture fluorescence images",
      "instruction": "Capture fluorescence images of Salmonella cells expressing pHluorin(M153R) using the EMCCD camera, ensuring to switch between excitation wavelengths."
    },
    {
      "id": "S13",
      "title": "Determine cytoplasmic pH",
      "instruction": "Analyze the captured fluorescence images to determine the bulk and local cytoplasmic pH using the ratio of fluorescence intensities at 410 nm and 470 nm."
    },
    {
      "id": "S14",
      "title": "Prepare cryo-EM samples",
      "instruction": "Prepare hook-basal bodies (HBBs) from Salmonella strains and apply a 3-μl solution onto a glow-discharged holey carbon grid."
    },
    {
      "id": "S15",
      "title": "Collect cryo-EM images",
      "instruction": "Quick-freeze the grids in liquid ethane and collect cryo-EM images using the Titan Krios electron microscope."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Expand Astrocytes",
      "instruction": "Obtain primary human astrocytes and expand them in Human Astrocyte Media supplemented with fetal bovine serum, penicillin-streptomycin, and Astrocyte Growth Supplement."
    },
    {
      "id": "S2",
      "title": "Culture Astrocytes",
      "instruction": "Culture astrocytes in a 50:50 mix of F10:MEMα media supplemented with 10% FBS and 1% penicillin-streptomycin."
    },
    {
      "id": "S3",
      "title": "Treat Astrocytes with Antibody",
      "instruction": "Treat astrocytes with 11 μg/ml of IGF1R-specific monoclonal antibody MAB391 for 24 hours to reduce IGF1R levels."
    },
    {
      "id": "S4",
      "title": "Wash and Culture Astrocytes",
      "instruction": "After 24 hours, wash the astrocytes with 1× PBS and culture them for an additional 72 hours in fresh F10:MEMα media."
    },
    {
      "id": "S5",
      "title": "Grow LUHMES Cells",
      "instruction": "Grow LUHMES cells in proliferation medium consisting of DMEM/F12 GlutaMAX™, N2 supplement, and 40 ng/ml recombinant FGF."
    },
    {
      "id": "S6",
      "title": "Differentiate LUHMES Cells",
      "instruction": "When LUHMES cells reach 50-60% confluence, replace the media with differentiation media containing DMEM/F12 GlutaMAX™, N2 supplement, and 1 μg/ml tetracycline."
    },
    {
      "id": "S7",
      "title": "Replate LUHMES Cells",
      "instruction": "After two days of differentiation, trypsinize LUHMES cells and replate them onto appropriate plates for an additional three days."
    },
    {
      "id": "S8",
      "title": "Transduce GFP LUHMES",
      "instruction": "Transduce low passage proliferating LUHMES with GFP-expressing lentiviral particles for 24 hours, then replace media with fresh proliferation media."
    },
    {
      "id": "S9",
      "title": "Co-culture Astrocytes and LUHMES",
      "instruction": "Seed astrocytes onto fibronectin-coated 24-well plates at a density of 30,000 cells/well, and add differentiation media to a separate flask of LUHMES."
    },
    {
      "id": "S10",
      "title": "Replate LUHMES onto Astrocytes",
      "instruction": "Two days later, replate LUHMES cells onto the astrocytes at a density of 7,500 cells/well and maintain co-cultures in differentiation media for 24 hours."
    },
    {
      "id": "S11",
      "title": "Treat Co-cultures with H2O2",
      "instruction": "After 72 hours of co-culture, treat the cells with 50 μM H2O2 for 2 hours."
    },
    {
      "id": "S12",
      "title": "Prepare Astrocyte Lysates",
      "instruction": "Remove the medium, wash cells with ice-cold PBS, and lyse them in extra strong lysis buffer. Incubate on ice, sonicate, and centrifuge."
    },
    {
      "id": "S13",
      "title": "Perform SDS-PAGE",
      "instruction": "Load 40 μg of protein onto SDS-PAGE gels, transfer to nitrocellulose membranes, block, and probe with primary and secondary antibodies."
    },
    {
      "id": "S14",
      "title": "Conduct Immunocytochemistry",
      "instruction": "Fix cells in paraformaldehyde, permeabilize, block, and incubate with primary antibodies followed by secondary antibodies. Stain nuclei with Hoechst 33342."
    },
    {
      "id": "S15",
      "title": "Analyze Neurite Outgrowth",
      "instruction": "Fix co-cultured cells, stain nuclei, capture images, and measure neurite lengths using ImageJ."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Cell Preparation",
      "instruction": "Enrich A-CD8+ T cells from individual A to obtain 2 × 10^6 cells."
    },
    {
      "id": "S2",
      "title": "Cell Stimulation",
      "instruction": "Stimulate A-CD8+ T cells with 1 × 10^6 B-APCs from individual B in 24-well plates, adding IL-2 (20 U/ml), IL-7 (50 ng/ml), and IL-15 (50 ng/ml)."
    },
    {
      "id": "S3",
      "title": "Incubation",
      "instruction": "Incubate the stimulated cells for 9 days to allow for expansion."
    },
    {
      "id": "S4",
      "title": "Cell Enrichment",
      "instruction": "After incubation, enrich the in vitro-expanded CD8+ CD28− T cells."
    },
    {
      "id": "S5",
      "title": "CFSE Labeling",
      "instruction": "Label A-CD4+ T cells from individual A with CFSE at a concentration of 5 × 10^4 cells/well."
    },
    {
      "id": "S6",
      "title": "Co-culture Setup",
      "instruction": "Co-culture CFSE-labeled A-CD4+ T cells with either B-APCs or I-APCs at 5 × 10^4 cells/well in a 96-well round bottom plate, with or without the in vitro-expanded CD8+ CD28− T cells at 2.5 × 10^4 cells/well."
    },
    {
      "id": "S7",
      "title": "Incubation for Proliferation",
      "instruction": "Incubate the co-culture for 7 days and then for an additional 11 days."
    },
    {
      "id": "S8",
      "title": "Proliferation Assessment",
      "instruction": "Use the CFSE dilution assay to assess the proliferation of CD4+ T cells after the incubation periods."
    },
    {
      "id": "S9",
      "title": "Data Analysis",
      "instruction": "Analyze the percentage of proliferating A-CD4+ T cells and compare the suppression effects between B-APCs and I-APCs."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Seed Sowing",
      "instruction": "Sow seeds of Phaseolus vulgaris genotypes in vermiculite and place them in a growth chamber at 23°C with a 16 h light/8 h dark cycle and 75% relative humidity."
    },
    {
      "id": "S2",
      "title": "Seedling Cultivation",
      "instruction": "Grow seedlings in plastic pots filled with moist vermiculite for 10-12 days until primary leaves are fully expanded."
    },
    {
      "id": "S3",
      "title": "Transplant Seedlings",
      "instruction": "Transplant three seedlings into a 20 cm plastic pot filled with moist vermiculite and place them in a dark room for 24 hours prior to inoculation."
    },
    {
      "id": "S4",
      "title": "Prepare DNA-Plasmid Mix",
      "instruction": "For primary inoculation, prepare a 20 μL DNA-plasmid mix using 50 mM potassium phosphate buffer, pH 7.0."
    },
    {
      "id": "S5",
      "title": "Prepare Leaf Sap for Secondary Inoculation",
      "instruction": "For secondary inoculations, grind an infected leaf of P. vulgaris cv. Black Valentine in a mortar with mock buffer to create leaf sap."
    },
    {
      "id": "S6",
      "title": "Perform Primary Inoculation",
      "instruction": "Inoculate one primary leaf of the seedlings by mechanical rubbing with the prepared DNA-plasmid mix."
    },
    {
      "id": "S7",
      "title": "Perform Secondary Inoculation",
      "instruction": "Inoculate the seedlings with the prepared leaf sap from the infected leaf using mechanical rubbing."
    },
    {
      "id": "S8",
      "title": "Incubate Inoculated Plants",
      "instruction": "Allow the inoculated plants to grow at 19°C under a 16 h light/8 h dark cycle in a growth chamber."
    },
    {
      "id": "S9",
      "title": "GFP Imaging",
      "instruction": "Examine GFP expression in aerial organs and roots using a UV lamp and photograph the results with a digital camera."
    },
    {
      "id": "S10",
      "title": "RNA Extraction and cDNA Synthesis",
      "instruction": "Extract total RNA and synthesize cDNA as per the established protocols."
    },
    {
      "id": "S11",
      "title": "Perform RT-PCR",
      "instruction": "Use specific primers to amplify the PvPDS gene and the internal control PvUBI gene, followed by analysis of PCR products using agarose-ethidium bromide electrophoresis."
    },
    {
      "id": "S12",
      "title": "Map R-BPMV Gene",
      "instruction": "Use MAPMAKER software to analyze segregation ratios and establish linkage groups for the R-BPMV resistance gene."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Obtain Patient Samples",
      "instruction": "Collect a total of 166 blood samples from 41 patients who meet the World Health Organization criteria for probable SARS cases."
    },
    {
      "id": "S2",
      "title": "Prepare Cell Lines",
      "instruction": "Culture all cell lines in Dulbecco’s Modified Eagle Medium (DMEM) supplemented with 10% fetal calf serum and penicillin/streptomycin."
    },
    {
      "id": "S3",
      "title": "Construct QT6/ACE2 Cell Line",
      "instruction": "Clone the ACE2 gene from a human kidney cDNA library and subclone it into pcdna3.1+. Transfect QT6 cells using lipofectamine 2000 and select for G418-resistant cells."
    },
    {
      "id": "S4",
      "title": "Split 293T Cells",
      "instruction": "Split confluent plates of 293T cells at a ratio of 1:4 the day before transfection."
    },
    {
      "id": "S5",
      "title": "Transfect 293T Cells",
      "instruction": "Transfect each plate of 293T cells with 1 μg gag/pol construct, 1.5 μg enhanced GFP reporter construct, and 1.5 μg envelope-expressing construct using Fugene-6 transfection reagent."
    },
    {
      "id": "S6",
      "title": "Harvest Viral Supernatant",
      "instruction": "Collect the supernatant from transfected 293T cells 48 hours and 72 hours post-transfection, filter through 0.45-μm filters, and store at -80°C."
    },
    {
      "id": "S7",
      "title": "Measure Viral Titer",
      "instruction": "Infect 293T, TE671, and QT6/ACE2 cells with the harvested viral supernatant and measure eGFP titers 72 hours later using fluorescence-activated cell sorting (FACS)."
    },
    {
      "id": "S8",
      "title": "Heat Inactivate Serum Samples",
      "instruction": "Heat inactivate patient serum samples at 56°C for 30 minutes."
    },
    {
      "id": "S9",
      "title": "Perform Live Virus Neutralization Assay",
      "instruction": "Dilute the heat-inactivated serum samples serially from 1:10 in culture medium, add 50 PFU of SARS Frankfurt strain, and incubate for 1 hour at 37°C before adding Vero E6 cells."
    },
    {
      "id": "S10",
      "title": "Assess Neutralization by CPE",
      "instruction": "Incubate the virus and serum mix with Vero E6 cells in 96-well plates for 4 days, then assess neutralization based on cytopathic effect (CPE)."
    },
    {
      "id": "S11",
      "title": "Perform Pseudotype Neutralization Assay",
      "instruction": "Dilute heat-inactivated serum samples 2-fold from 1:10 and mix with MLV(SARS) virions at a 1:1 vol/vol ratio, then incubate for 1 hour at 37°C."
    },
    {
      "id": "S12",
      "title": "Add Serum Dilutions to QT6/ACE2 Cells",
      "instruction": "Add 100 μL of each serum dilution to QT6/ACE2 cells seeded at 1 × 10^4 cells per well in 96-well plates and incubate."
    },
    {
      "id": "S13",
      "title": "Count GFP-Positive Cells",
      "instruction": "Count the number of GFP-positive cells 48 hours after adding the serum dilutions using fluorescence microscopy."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Generate stn1 mutants",
      "instruction": "Cross Arabidopsis ecotypes with short and long telomeres to produce stn1 mutants."
    },
    {
      "id": "S2",
      "title": "Analyze phenotypes",
      "instruction": "Categorize the resulting stn1 mutants into five phenotypic categories based on growth defects and reproductive capabilities."
    },
    {
      "id": "S3",
      "title": "Assess telomere length",
      "instruction": "Measure the average telomere length in G1 stn1 mutants and compare it with G1 stn1(W/C) mutants."
    },
    {
      "id": "S4",
      "title": "Generate exo1 stn1 mutants",
      "instruction": "Create exo1a exo1b stn1 mutants by disrupting both EXO1 paralogues in Arabidopsis."
    },
    {
      "id": "S5",
      "title": "Evaluate developmental defects",
      "instruction": "Compare the growth defects and fertility of G1 exo1 stn1 mutants with G1 stn1 mutants."
    },
    {
      "id": "S6",
      "title": "Perform TRF analysis",
      "instruction": "Conduct terminal restriction fragment analysis to quantify telomeric DNA in stn1 and exo1 stn1 mutants."
    },
    {
      "id": "S7",
      "title": "Conduct in gel hybridization",
      "instruction": "Use in gel hybridization to compare G-overhang sizes between stn1 and exo1 stn1 plants."
    },
    {
      "id": "S8",
      "title": "Generate telomerase-null mutants",
      "instruction": "Create telomerase-null stn1 and exo1 stn1 mutants by disrupting the TERT gene."
    },
    {
      "id": "S9",
      "title": "Assess growth defects in telomerase-null mutants",
      "instruction": "Evaluate the growth defects in stn1 tert and exo1 stn1 tert mutants compared to their respective controls."
    },
    {
      "id": "S10",
      "title": "Quantify telomere length",
      "instruction": "Measure and compare telomere lengths among siblings from stn1 tert and exo1 stn1 tert mutants."
    },
    {
      "id": "S11",
      "title": "Perform t-circle amplification assay",
      "instruction": "Analyze t-circle abundance in pol α and icu2-1 mutants to assess telomere dysfunction."
    },
    {
      "id": "S12",
      "title": "Analyze chromosome fusions",
      "instruction": "Use fusion PCR to detect chromosome end-to-end fusions in stn1, pol α, and icu2-1 mutants."
    },
    {
      "id": "S13",
      "title": "Evaluate anaphase bridges",
      "instruction": "Count the frequency of anaphase bridges in pol α and icu2-1 mutants to assess genome instability."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Cell Line Selection",
      "instruction": "Select three human metastatic TNBC cell lines: BT-549, MDA-MB-468, and MDA-MB-231 for the study."
    },
    {
      "id": "S2",
      "title": "Agonist Treatment",
      "instruction": "Treat MDA-MB-231 and MDA-MB-468 cells with ATP and BT-549 cells with histamine to evoke cytosolic Ca2+ transients."
    },
    {
      "id": "S3",
      "title": "MCU Silencing",
      "instruction": "Use short-interfering RNA (siRNA) to silence MCU in the selected TNBC cell lines and confirm silencing efficiency."
    },
    {
      "id": "S4",
      "title": "Mitochondrial Ca2+ Uptake Measurement",
      "instruction": "Measure mitochondrial Ca2+ uptake in response to agonist treatment in MCU-silenced cells and compare with control cells."
    },
    {
      "id": "S5",
      "title": "Wound Healing Assay",
      "instruction": "Perform a wound healing migration assay to assess the effect of MCU silencing on cell motility in all TNBC lines."
    },
    {
      "id": "S6",
      "title": "Cytosolic Ca2+ Transient Measurement",
      "instruction": "Measure agonist-induced cytosolic Ca2+ transients in BT-549 and MDA-MB-231 cells to evaluate the impact of MCU silencing."
    },
    {
      "id": "S7",
      "title": "SOCE Measurement",
      "instruction": "Assess store-operated Ca2+ entry (SOCE) in MCU-silenced and control cells using various protocols to deplete Ca2+ stores."
    },
    {
      "id": "S8",
      "title": "Spheroid Formation Assay",
      "instruction": "Generate stable MCU-silenced cells and perform an in vitro spheroid formation assay to evaluate invasion potential."
    },
    {
      "id": "S9",
      "title": "In Vivo Tumor Analysis",
      "instruction": "Use CRISPR/Cas9 technology to generate MCU−/− MDA-MB-231 cells and inject them into SCID mice for tumor growth analysis."
    },
    {
      "id": "S10",
      "title": "Tumor Measurement",
      "instruction": "Monitor tumor size, lymph node infiltration, and metastasis formation in mice injected with MCU−/− cells versus control cells."
    },
    {
      "id": "S11",
      "title": "NADH and ATP Measurement",
      "instruction": "Measure cellular and mitochondrial NADH levels, NADPH levels, and ATP production using live cell fluorescent and luminescent techniques."
    },
    {
      "id": "S12",
      "title": "Mitochondrial ROS Measurement",
      "instruction": "Use the pHyper-dMito protein sensor to measure mitochondrial hydrogen peroxide (H2O2) levels in MCU-silenced cells."
    },
    {
      "id": "S13",
      "title": "Data Analysis",
      "instruction": "Analyze all collected data to assess the impact of MCU silencing on mitochondrial Ca2+ uptake, cell migration, and redox metabolism."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Cell Suspension Preparation",
      "instruction": "Prepare a cell suspension of planarian cells for staining."
    },
    {
      "id": "S2",
      "title": "Staining with Hoechst and MTG",
      "instruction": "Stain the cell suspension with Hoechst 33,342 and MTG to visualize the nuclear content and mitochondrial mass."
    },
    {
      "id": "S3",
      "title": "Cell Population Identification",
      "instruction": "Identify three distinct cell populations (X1, X2, Xins) based on their nuclear content using fluorescence microscopy."
    },
    {
      "id": "S4",
      "title": "Verapamil Treatment",
      "instruction": "Treat the cells with Verapamil to inhibit efflux pumps and then restain with MTG to assess changes in fluorescence intensity."
    },
    {
      "id": "S5",
      "title": "Antibody Generation",
      "instruction": "Generate and characterize an antibody specific to PIWI-1 for subsequent immunostaining."
    },
    {
      "id": "S6",
      "title": "Immunostaining with PIWI-1 Antibody",
      "instruction": "Perform immunostaining of planarian cells using the generated PIWI-1 antibody to identify High, Low, and negative PIWI-1 expressing cells."
    },
    {
      "id": "S7",
      "title": "Flow Cytometry Analysis",
      "instruction": "Analyze the stained cells by flow cytometry to separate populations based on PIWI-1 expression and cell size."
    },
    {
      "id": "S8",
      "title": "RNA Sequencing",
      "instruction": "Perform RNA sequencing on the X1-MTG Low and X1-MTG High populations to analyze gene expression differences."
    },
    {
      "id": "S9",
      "title": "Gene Ontology Analysis",
      "instruction": "Conduct gene ontology analysis on differentially expressed genes to identify functional categories related to differentiation."
    },
    {
      "id": "S10",
      "title": "Transcriptome Comparison",
      "instruction": "Compare the transcriptome data of X1-MTG Low and High cells with published single-cell transcriptome data to assess neoblast heterogeneity."
    },
    {
      "id": "S11",
      "title": "X2 Population Analysis",
      "instruction": "Stain the X2 population with PIWI-1 antibody and analyze the expression patterns of PIWI-1 in relation to MTG signals."
    },
    {
      "id": "S12",
      "title": "RNA-seq on X2 Populations",
      "instruction": "Perform RNA sequencing on the four populations derived from X2-MTG Low and High cells to investigate their transcriptomic profiles."
    },
    {
      "id": "S13",
      "title": "Cell Cycle Analysis",
      "instruction": "Conduct cell cycle analysis on sorted cells from X2-MTG Low to confirm their phase in the cell cycle."
    },
    {
      "id": "S14",
      "title": "Transplantation Experiment",
      "instruction": "Inject the MTG populations into lethally irradiated animals to assess their potential as pluripotent stem cells."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Animal Preparation",
      "instruction": "Use fluorescence reporter mice or ICR mice for the experiments. Sacrifice the mice by cervical dislocation at E15.5 or E16.5."
    },
    {
      "id": "S2",
      "title": "Tissue Dissection",
      "instruction": "Surgically excise the epididymides from the mice, ensuring to include the region of the vas deferens close to the tail."
    },
    {
      "id": "S3",
      "title": "Tissue Fixation",
      "instruction": "Fix the dissected epididymides with either 4% PFA in PBS for 2 hours at 4°C or 20 minutes at 37°C, or with 2% TCA in Ca2+- and Mg2+-free PBS for 20 minutes at 4°C."
    },
    {
      "id": "S4",
      "title": "Blocking",
      "instruction": "Block the samples by incubating in 10% normal goat serum or normal donkey serum diluted in 0.1% Triton X-100/PBS for 3 hours at 37°C."
    },
    {
      "id": "S5",
      "title": "Primary Antibody Incubation",
      "instruction": "Incubate the samples with primary antibodies overnight at 4°C."
    },
    {
      "id": "S6",
      "title": "Secondary Antibody Incubation",
      "instruction": "Incubate the samples with secondary antibodies conjugated to Alexa Fluor 546 or Alexa Fluor 647 overnight at 4°C."
    },
    {
      "id": "S7",
      "title": "Visualization Staining",
      "instruction": "Stain the samples with TRITC-conjugated phalloidin and Hoechst 33342 for visualization of F-actin and DNA, respectively."
    },
    {
      "id": "S8",
      "title": "Sample Mounting",
      "instruction": "Mount the samples with 10 µl of 1% agarose gel on a glass-based dish for stable imaging."
    },
    {
      "id": "S9",
      "title": "Optical Clearing",
      "instruction": "Immerse the samples in BABB solution or CUBIC2 solution for optical clearing."
    },
    {
      "id": "S10",
      "title": "Volumetric Imaging",
      "instruction": "Obtain 8-bit volumetric fluorescence images using a confocal laser-scanning platform with appropriate objective lens magnifications."
    },
    {
      "id": "S11",
      "title": "Organ Culture Setup",
      "instruction": "Place the epididymides on a hydrophilic polytetrafluoroethylene organ culture insert in a 35 mm Petri dish filled with culture medium at 37°C under 5% CO2."
    },
    {
      "id": "S12",
      "title": "Live Imaging",
      "instruction": "Perform live imaging using a multiphoton fluorescence microscope with specified imaging conditions."
    },
    {
      "id": "S13",
      "title": "Tissue Compression Assay",
      "instruction": "Prepare the PDMS chamber, place the epididymides in it, fill with collagen, and apply compression before incubating for analysis."
    },
    {
      "id": "S14",
      "title": "Total Protein Extraction",
      "instruction": "Extract total protein from the epididymides using RIPA buffer and disrupt using an ultrasonic cell disruptor."
    },
    {
      "id": "S15",
      "title": "Western Blotting",
      "instruction": "Prepare lysates for SDS-PAGE, run the gel, transfer proteins to a membrane, and perform immunoblotting with specific antibodies."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Scan CoREGs",
      "instruction": "Scan each cloned HAG maize CoREG for the presence of an acetyl-CoA-binding site using the Conserved Domain Database (CDD)."
    },
    {
      "id": "S2",
      "title": "Align Related Proteins",
      "instruction": "Align related proteins using Clustal W with default parameters in the megalign program within the DNASTAR Lasergene package."
    },
    {
      "id": "S3",
      "title": "Align AUX/IAA CoREGs",
      "instruction": "Align full-length amino acid sequences of AUX/IAA CoREGs using MUSCLE with specified parameters."
    },
    {
      "id": "S4",
      "title": "Export Alignments",
      "instruction": "Export each multiple sequence alignment in Newick format for phylogenetic analysis."
    },
    {
      "id": "S5",
      "title": "Clone Constructs",
      "instruction": "Clone constructs into either the pENTR®/D-TOPO® or pENTR®/SD/D-TOPO® vector using high-fidelity Phusion® polymerase."
    },
    {
      "id": "S6",
      "title": "Optimize PCR Conditions",
      "instruction": "Optimize PCR conditions by adjusting DMSO, MgCl2, or annealing temperature as needed."
    },
    {
      "id": "S7",
      "title": "Screen Colonies",
      "instruction": "Screen kanamycin-resistant colonies for inserts of the correct size and orientation using colony PCR or restriction digestion."
    },
    {
      "id": "S8",
      "title": "Confirm Insert Sequence",
      "instruction": "Confirm the sequence of cloned inserts by single-read paired-end Sanger dideoxy sequencing."
    },
    {
      "id": "S9",
      "title": "Isolate DNA",
      "instruction": "Isolate genomic DNA from B73 plant tissue using a CTAB-based method."
    },
    {
      "id": "S10",
      "title": "Isolate RNA",
      "instruction": "Isolate total RNA from non-starchy B73 tissues using RNAzol® according to the manufacturer's protocol."
    },
    {
      "id": "S11",
      "title": "Synthesize cDNA",
      "instruction": "Treat total RNA samples with Turbo DNA-free® to remove contaminating DNA, then synthesize complementary DNA using Maxima H Minus® Reverse Transcriptase."
    },
    {
      "id": "S12",
      "title": "Perform RT-PCR",
      "instruction": "Amplify TFs by RT-PCR from tissues where they are expected to be highly expressed."
    },
    {
      "id": "S13",
      "title": "Prepare Maize Protoplasts",
      "instruction": "Chop and digest leaves from 13-day-old maize seedlings to prepare protoplasts for transformation."
    },
    {
      "id": "S14",
      "title": "Electroporate Protoplasts",
      "instruction": "Electroporate protoplasts with total DNA using specified voltage and pulse conditions."
    },
    {
      "id": "S15",
      "title": "Analyze Transformation Efficiency",
      "instruction": "Incubate protoplasts and then analyze transformation efficiency by assessing GFP expression under a fluorescence microscope."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Probe Design",
      "instruction": "Design probes by generating variable length sequences (50- to 100-mers) across the target sequence, ensuring to mask repeats and eliminate probes with excessive matches."
    },
    {
      "id": "S2",
      "title": "Hybridization Setup",
      "instruction": "Prepare the array design using the selected probe set and random probes, then hybridize the array with barley cultivars for 4 days following standard CGH protocols."
    },
    {
      "id": "S3",
      "title": "Probe Filtering",
      "instruction": "Remove probes based on CGH results, excluding those identified as missed repetitive elements or contaminants, to create a solution-phase capture pool."
    },
    {
      "id": "S4",
      "title": "Library Preparation",
      "instruction": "Fragment 1 μg of genomic DNA into 200–300 bp using a Covaris S220 Instrument, then prepare Illumina TruSeq Paired End libraries according to the manufacturer's instructions."
    },
    {
      "id": "S5",
      "title": "Pre-Capture LM-PCR",
      "instruction": "Use 20 μl of the TruSeq DNA library in a ligation-mediated PCR reaction to enrich for correctly ligated fragments, then clean up and quantify the DNA."
    },
    {
      "id": "S6",
      "title": "Hybridization Cocktail Preparation",
      "instruction": "Add Roche NimbleGen's Plant Capture Enhancer and specific index oligos to the amplified sample library, then dry down the mixture."
    },
    {
      "id": "S7",
      "title": "Hybridization",
      "instruction": "Prepare the hybridization sample by adding Sequence Capture Hybridization Buffer and Hybridization Component A, then incubate in a thermocycler for 64–72 hours."
    },
    {
      "id": "S8",
      "title": "Bead Preparation",
      "instruction": "Prepare Streptavidin Dynabeads for affinity purification by vortexing, aliquoting, and washing them before adding the hybridization sample."
    },
    {
      "id": "S9",
      "title": "Capture Binding",
      "instruction": "Mix the hybridization sample with the Dynabeads and incubate at 47°C for 45 minutes, ensuring the beads remain in suspension by vortexing periodically."
    },
    {
      "id": "S10",
      "title": "Washing Dynabeads",
      "instruction": "Wash the Dynabeads with SC Wash Buffer I and Stringent Wash Buffer, ensuring to maintain the temperature and discarding the supernatant after each wash."
    },
    {
      "id": "S11",
      "title": "Library Amplification",
      "instruction": "Amplify the bead-bound captured library using LM-PCR, then clean up the reaction using the Qiaquick PCR purification kit according to the manufacturer's instructions."
    },
    {
      "id": "S12",
      "title": "Library Quantification",
      "instruction": "Quantify the purified library using a NanoDrop spectrophotometer and analyze the library fragments using an Agilent Bioanalyzer."
    },
    {
      "id": "S13",
      "title": "Data Analysis",
      "instruction": "Map the target regions against the barley genome assembly using BWA and Mega BLAST, then compute coverage and perform SNP calling using SAMtools."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Culture D. coniospora",
      "instruction": "Inoculate roughly 10^9 fresh spores of D. coniospora in 100 mL of NGMY medium and culture for 7 days at 25°C."
    },
    {
      "id": "S2",
      "title": "Harvest mycelia",
      "instruction": "After 7 days, harvest the mycelia by vacuum filtering through a sterile 10 μm nylon membrane."
    },
    {
      "id": "S3",
      "title": "Dry mycelia",
      "instruction": "Place the filter containing mycelia in a 30°C incubator for approximately 3 hours until dry."
    },
    {
      "id": "S4",
      "title": "Grind mycelia",
      "instruction": "Manually grind the dried mycelia in a liquid nitrogen-cooled mortar."
    },
    {
      "id": "S5",
      "title": "Extract genomic DNA",
      "instruction": "Transfer a 20 mg aliquot of the ground mycelia to a 1.5 mL tube and extract DNA using the DNeasy Plant Mini Kit according to the manufacturer's instructions."
    },
    {
      "id": "S6",
      "title": "Prepare RNA samples",
      "instruction": "Collect fresh spores from 10 cm NGM plates of infected worms and inoculate in 100 mL of NGMY liquid medium, culturing for either 4 days or through serial cultures."
    },
    {
      "id": "S7",
      "title": "Filter and freeze samples",
      "instruction": "Filter the cultures through 0.22 μm Steritop units, flash freeze in liquid nitrogen, and store at -80°C."
    },
    {
      "id": "S8",
      "title": "Homogenize samples for RNA extraction",
      "instruction": "Dissolve 200 mg of spores or mycelia in 1 mL Trizol in lysing matrix tubes, homogenize for 20 seconds at 6 m/s, incubate on ice for 2 minutes, and homogenize a second time."
    },
    {
      "id": "S9",
      "title": "Purify RNA",
      "instruction": "Purify the RNA using a standard protocol and clean it with an RNeasy mini Kit."
    },
    {
      "id": "S10",
      "title": "Prepare sequencing libraries",
      "instruction": "Prepare MIseq paired-end libraries from genomic DNA and sequence on an Illumina MIseq sequencer following the manufacturer's standard procedures."
    },
    {
      "id": "S11",
      "title": "Perform SOLiD sequencing",
      "instruction": "Prepare two mate-paired libraries from D. coniospora genomic DNA, shearing DNA to 1.5 kb or 3 kb fragments, and amplify through 14 rounds of PCR."
    },
    {
      "id": "S12",
      "title": "Size-select and purify fragments",
      "instruction": "Size-select fragments between 250 and 300 bp using a 4% acrylamide gel and purify with the SOLiD Library Micro Column Purification Kit."
    },
    {
      "id": "S13",
      "title": "Perform de novo genome assembly",
      "instruction": "Process MIseq reads with BBDuk to filter contaminants and low-quality reads, then perform de novo genome assembly using Velvet, SPAdes, SOAPdenovo2, and ABySS."
    },
    {
      "id": "S14",
      "title": "Conduct optical mapping",
      "instruction": "Generate a whole genome map using the Argus Whole-Genome Mapping System and sort molecules longer than 200 kb for assembly."
    },
    {
      "id": "S15",
      "title": "Perform gene prediction",
      "instruction": "Use Augustus for gene prediction on the assembled genome, trained with Trinity-derived transcripts, and annotate using Interproscan."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "siRNA Dispensing",
      "instruction": "Dispense siRNA SMARTpools at 0.3 µM in 10 µl volumes into triplicate black 384-well plates using a Rapidplate384 liquid handler."
    },
    {
      "id": "S2",
      "title": "Plate Sealing and Storage",
      "instruction": "Seal the plates with adhesive seals and plastic lids, then store them at −80°C for a minimum of 24 hours and a maximum of 48 hours."
    },
    {
      "id": "S3",
      "title": "Thaw Plates",
      "instruction": "On the day of transfection, thaw the assay plates at room temperature."
    },
    {
      "id": "S4",
      "title": "Add Transfection Reagent",
      "instruction": "Add 10 µl of transfection reagent diluted in Hank's buffered saline solution to each well using a Multidrop 384."
    },
    {
      "id": "S5",
      "title": "Incubate for Complex Formation",
      "instruction": "Incubate the plates at room temperature for 20 minutes to allow the formation of transfection complexes."
    },
    {
      "id": "S6",
      "title": "Prepare HeLa Cells",
      "instruction": "Wash low-passage HeLa cells in PBS, trypsinize them, and dilute in phenol red-free, antibiotic-free transfection medium."
    },
    {
      "id": "S7",
      "title": "Count and Seed Cells",
      "instruction": "Count the cells and add 3×10^3 cells in 40 µl to each well using the Multidrop 384."
    },
    {
      "id": "S8",
      "title": "Incubate Cells",
      "instruction": "Incubate the plates for 48 hours at 37°C in a humidified incubator with 5% CO2."
    },
    {
      "id": "S9",
      "title": "Infection Setup",
      "instruction": "Remove media from the plates by inversion and add 10 µl of infection media or virus using the Multidrop 384."
    },
    {
      "id": "S10",
      "title": "Incubate for Infection",
      "instruction": "Incubate the plates at 37°C for 1 hour before adding 50 µl of infection media and returning the plates to the incubator."
    },
    {
      "id": "S11",
      "title": "Monitor Virus Replication",
      "instruction": "Monitor virus replication as a function of eGFP fluorescence from 24 to 80 hours post-infection using a plate reader."
    },
    {
      "id": "S12",
      "title": "Cell Viability Assay",
      "instruction": "Add 5 µl of CellTiter Blue reagent to each well and incubate for 2 hours at 37°C before measuring fluorescence."
    },
    {
      "id": "S13",
      "title": "Data Normalization",
      "instruction": "Normalize the readings to the viability of mock-transfected cells and calculate the mean cell viability over three replicates."
    },
    {
      "id": "S14",
      "title": "Deconvolution of siRNA SMARTpools",
      "instruction": "Dilute individual siRNAs and reconstituted SMARTpool to 0.3 µM, dispense into plates, and perform transfection and infection as previously described."
    },
    {
      "id": "S15",
      "title": "Validation of Phenotype",
      "instruction": "Calculate replication slopes and normalize them; validate the phenotype if two or more siRNAs show the same or better results."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Select AAV Vector",
      "instruction": "Choose the serotype 6 AAV (AAV6) vector for its infectivity in mouse and human embryonic stem cells."
    },
    {
      "id": "S2",
      "title": "Prepare Viral Vectors",
      "instruction": "Prepare viral vectors (AAV, adenoviral, and lentiviral) encoding enhanced green fluorescent protein (EGFP) driven by the CAG promoter."
    },
    {
      "id": "S3",
      "title": "Microinject Viral Vectors",
      "instruction": "Microinject each viral vector into the perivitelline space of pronuclear-stage mouse embryos."
    },
    {
      "id": "S4",
      "title": "Confirm EGFP Expression",
      "instruction": "At the morula/blastocyst stage, confirm the expression of EGFP under a fluorescence microscope."
    },
    {
      "id": "S5",
      "title": "Remove Zona Pellucida",
      "instruction": "Remove the zona pellucida from embryos to enable efficient infection by the lentiviral vector."
    },
    {
      "id": "S6",
      "title": "Electroporate Embryos",
      "instruction": "Introduce Cas9-RNP into pronuclear-stage embryos by electroporation."
    },
    {
      "id": "S7",
      "title": "Inject scAAV Vector",
      "instruction": "Inject a self-complementary AAV (scAAV) vector harboring a donor DNA cassette into the embryos post-electroporation."
    },
    {
      "id": "S8",
      "title": "Assess Knockin Efficiency",
      "instruction": "At the blastocyst stage, assess the efficiency of knockin at the Rosa26 locus."
    },
    {
      "id": "S9",
      "title": "Confirm Germline Transmission",
      "instruction": "Breed knockin founders with wild-type mice and genotype N1 generation offspring to confirm germline transmission."
    },
    {
      "id": "S10",
      "title": "Perform Flow Cytometry",
      "instruction": "Conduct flow cytometry on peripheral blood to confirm EGFP expression in offspring."
    },
    {
      "id": "S11",
      "title": "Analyze Integration Sites",
      "instruction": "Perform Sanger sequencing and restriction fragment-length polymorphism analysis to confirm correct insertion of the donor DNA."
    },
    {
      "id": "S12",
      "title": "Evaluate Phenotype Rescue",
      "instruction": "Assess the restoration of the nude phenotype in mice with exchanged wild-type exon 3."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Cell Culture Setup",
      "instruction": "Grow 293T and 293L cells in high-glucose DMEM supplemented with 8% bovine growth serum, 2 mM l-glutamine, penicillin, and streptomycin. For specific 293L cells, add 50μg/mL hygromycin B."
    },
    {
      "id": "S2",
      "title": "Induction of iSLK.219 Cells",
      "instruction": "Maintain iSLK.219 cells in DMEM with 10% Tet-Free Fetal Bovine Serum and antibiotics. Induce cells with doxycycline as needed."
    },
    {
      "id": "S3",
      "title": "Transduction of BCBL-1 Cells",
      "instruction": "Transduce BCBL-1 cells with shRNA PRMT5 lentiviral vectors and select using 1μg/mL puromycin."
    },
    {
      "id": "S4",
      "title": "Lentiviral Vector Production",
      "instruction": "Transfect 293T cells with pLVX-ORF59-Flag or pLVXdsRed-ORF59-Flag lentiviral vectors along with packaging vectors to produce virions."
    },
    {
      "id": "S5",
      "title": "Transduction of Target Cells",
      "instruction": "Add collected viruses to target cells for transduction and select with puromycin (2 mg/ml) to obtain a pure population."
    },
    {
      "id": "S6",
      "title": "Transfection of BAC16 ORF59-Flag",
      "instruction": "Transfect BAC16 ORF59-Flag into 293L cells using Metafectene Pro and select with hygromycin."
    },
    {
      "id": "S7",
      "title": "Cell Harvesting",
      "instruction": "After 48 hours post-transfection, harvest the transfected 293T cells for immunoprecipitation assays."
    },
    {
      "id": "S8",
      "title": "Cell Lysis",
      "instruction": "Wash harvested cells with ice-cold PBS and lyse in ice-cold RIPA buffer supplemented with protease inhibitors."
    },
    {
      "id": "S9",
      "title": "Immunoprecipitation",
      "instruction": "Preclear lysates with Protein A-Protein G-conjugated Sepharose beads, then add antibodies to capture proteins overnight at 4°C."
    },
    {
      "id": "S10",
      "title": "Western Blotting",
      "instruction": "Wash immunoprecipitated complexes, boil in Laemmli buffer, resolve on SDS-PAGE, and transfer to nitrocellulose membranes for antibody incubation."
    },
    {
      "id": "S11",
      "title": "Chromatin Immunoprecipitation",
      "instruction": "Cross-link approximately 20 million cells with formaldehyde, then wash and lyse to isolate nuclei for chromatin preparation."
    },
    {
      "id": "S12",
      "title": "Sonication of Chromatin",
      "instruction": "Sonicate chromatin to an average length of 700 bp, then centrifuge to remove debris."
    },
    {
      "id": "S13",
      "title": "ChIP Assay",
      "instruction": "Preclear chromatin with salmon sperm DNA-protein A-protein G Sepharose slurry, then capture chromatin with specific antibodies overnight."
    },
    {
      "id": "S14",
      "title": "DNA Elution and Purification",
      "instruction": "Elute chromatin in an elution buffer, reverse cross-link, treat with proteinase K, and purify DNA using Qiagen Min-Elute PCR purification columns."
    },
    {
      "id": "S15",
      "title": "Library Preparation for Sequencing",
      "instruction": "Prepare DNA sequencing libraries from extracted DNA using the NEXTflex Illumina ChIP-Seq Library Preparation Kit and analyze for purity."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Dissection of Drosophila Larval Brains",
      "instruction": "Dissect the required number of Drosophila larval brains in PBS after 48 hours of larval hatching."
    },
    {
      "id": "S2",
      "title": "Fixation of Drosophila Larval Brains",
      "instruction": "Fix the dissected larval brains with 1% formaldehyde in PBS for 10 minutes at room temperature."
    },
    {
      "id": "S3",
      "title": "Quenching Fixation",
      "instruction": "Quench the fixation by adding 125 mM glycine to the fixed larval brains."
    },
    {
      "id": "S4",
      "title": "Dissociation of Cells",
      "instruction": "Dissociate the fixed larval brains and resuspend the cells according to the established method."
    },
    {
      "id": "S5",
      "title": "Cell Sorting of Drosophila NSCs",
      "instruction": "Sort the dissociated cells on a BD FACSAria based on GFP strength and NSC size to obtain a pure population of type II NSCs."
    },
    {
      "id": "S6",
      "title": "Fixation of K562 Cells",
      "instruction": "Fix K562 cells cultured in RPMI medium with 10% Fetal Bovine Serum for 10 minutes at room temperature using 1% formaldehyde."
    },
    {
      "id": "S7",
      "title": "Quenching Fixation of K562 Cells",
      "instruction": "Quench the crosslinking in K562 cells with 125 mM glycine."
    },
    {
      "id": "S8",
      "title": "Cell Sorting of K562 Cells",
      "instruction": "Sort 100 K562 cells using Hoechst stain on a BD FACSAria cell sorter and collect them in RIPA buffer."
    },
    {
      "id": "S9",
      "title": "Sonication of NSCs",
      "instruction": "Resuspend 1.2 million FACS sorted NSCs in 140 mM RIPA and sonicate for 14 cycles at high settings."
    },
    {
      "id": "S10",
      "title": "Antibody Incubation",
      "instruction": "Incubate the sonicated samples overnight with 2 μg of specific antibody at 4°C with head-over-tail rotations."
    },
    {
      "id": "S11",
      "title": "Bead Capture of Antibodies",
      "instruction": "Add 20 μl of blocked Protein A and G Dynabeads to the samples and incubate for 3 hours to capture the antibodies."
    },
    {
      "id": "S12",
      "title": "Washing Beads",
      "instruction": "Wash the beads with specified buffers: once with 140 mM RIPA, four times with 250 mM RIPA, and twice with TE buffer."
    },
    {
      "id": "S13",
      "title": "Proteinase K Treatment",
      "instruction": "Treat the samples with Proteinase K for 12 hours at 37°C and at least 6 hours at 65°C to reverse cross-links."
    },
    {
      "id": "S14",
      "title": "DNA Recovery and Library Preparation",
      "instruction": "Recover the DNA from the samples, dissolve in TE buffer, and prepare libraries using the NebNext Ultra II DNA library preparation kit."
    },
    {
      "id": "S15",
      "title": "PCR Amplification and Purification",
      "instruction": "Amplify the libraries using PCR, purify with Ampure Xp beads, and analyze the size distribution and concentration."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Gene Screening",
      "instruction": "Screen publicly available datasets for Arabidopsis genes of unknown function that exhibit transcriptional signatures of CBGs or CCGs."
    },
    {
      "id": "S2",
      "title": "Protein Expression Analysis",
      "instruction": "Perform immunoblot analyses using BCM1 antiserum raised against recombinant Arabidopsis His-BCM1 to assess BCM1 protein accumulation in various tissues."
    },
    {
      "id": "S3",
      "title": "Transient Expression in Protoplasts",
      "instruction": "Fuse BCM1 to yellow fluorescent protein (YFP) and express in Arabidopsis protoplasts to observe chloroplast localization."
    },
    {
      "id": "S4",
      "title": "Chloroplast Fractionation",
      "instruction": "Isolate envelope, stroma, and thylakoid fractions from chloroplasts and analyze BCM1 distribution using immunoblotting."
    },
    {
      "id": "S5",
      "title": "Mutant Characterization",
      "instruction": "Characterize the status of TBS in bcm1 mutants and BCM1-overexpressing plants to assess their chlorophyll accumulation and phenotypes."
    },
    {
      "id": "S6",
      "title": "ALA Synthesis Measurement",
      "instruction": "Measure ALA synthesis rates in bcm1 mutants and BCM1-OX seedlings to evaluate the impact of BCM1 on chlorophyll biosynthesis."
    },
    {
      "id": "S7",
      "title": "Protein Level Analysis",
      "instruction": "Perform immunoblot analyses to assess the levels of chlorophyll biosynthesis enzymes (CBEs) in bcm1 and BCM1-OX seedlings."
    },
    {
      "id": "S8",
      "title": "Genetic Interaction Studies",
      "instruction": "Combine bcm1-3 mutants with gun5 and gun4 mutants to investigate the genetic interactions affecting chlorophyll biosynthesis."
    },
    {
      "id": "S9",
      "title": "Yeast Two-Hybrid Screening",
      "instruction": "Conduct a yeast two-hybrid screen to identify potential protein partners of BCM1 in the TBS pathway."
    },
    {
      "id": "S10",
      "title": "In Vitro MgCh Activity Assay",
      "instruction": "Isolate thylakoid membranes from bcm1-3 gun4-1 and BCM1-OX3/gun4-1 seedlings, and perform MgCh activity assays with recombinant components."
    },
    {
      "id": "S11",
      "title": "Recombinant Protein Expression",
      "instruction": "Express His-BCM1 in Saccharomyces cerevisiae cells and analyze its effect on MgCh activity using isolated yeast membranes."
    },
    {
      "id": "S12",
      "title": "Purification of BCM1",
      "instruction": "Purify recombinant His-BCM1 proteins using a non-ionic detergent and assess their impact on MgCh activity in vitro."
    },
    {
      "id": "S13",
      "title": "Data Analysis",
      "instruction": "Analyze the results from all experiments to draw conclusions about the role of BCM1 in chlorophyll biosynthesis and MgCh activity."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Mouse Strain Preparation",
      "instruction": "Obtain the required mouse strains: C57BL/6, Tlr7−/−, Tlr9−/−, and Myd88−/−. Confirm that all strains have a C57BL/6 background of greater than 95% by microsatellite genotyping."
    },
    {
      "id": "S2",
      "title": "Parasite Acquisition",
      "instruction": "Acquire P. berghei strain ANKA (MRA-311) parasites from the MR4 stock center and maintain them in C57BL/6 mice."
    },
    {
      "id": "S3",
      "title": "Blood Harvesting",
      "instruction": "On day 5 of infection, harvest blood by cardiac puncture from an infected mouse to obtain infected erythrocytes."
    },
    {
      "id": "S4",
      "title": "Infection of New Mouse",
      "instruction": "Introduce 10^6 infected erythrocytes into a new mouse via intraperitoneal injection in 100 μl of Alsever’s solution."
    },
    {
      "id": "S5",
      "title": "Initiate Infections",
      "instruction": "Initiate infections at 14:00 hours using the previously prepared infected mice."
    },
    {
      "id": "S6",
      "title": "Monitor Survival and Symptoms",
      "instruction": "Monitor the mice daily for survival and signs of cerebral malaria, increasing monitoring to twice daily during the peak lethality period (days 6 through 12)."
    },
    {
      "id": "S7",
      "title": "Assess Neurological Symptoms",
      "instruction": "Identify any neurological symptoms such as convulsions, ataxia, or paralysis in the mice, and record any deaths occurring on or before day 12 post-infection."
    },
    {
      "id": "S8",
      "title": "Monitor Parasitaemia",
      "instruction": "Daily monitor parasitaemia by performing Giemsa-stained thin film blood smears to determine the percentage of parasite-infected erythrocytes."
    },
    {
      "id": "S9",
      "title": "Cytokine Analysis Preparation",
      "instruction": "For cytokine analysis, collect blood by submandibular blood collection or cardiac puncture into K2EDTA tubes for plasma isolation."
    },
    {
      "id": "S10",
      "title": "Cytokine Detection",
      "instruction": "Measure all plasma cytokines using a multiplexed cytometric bead immunoassay according to the manufacturer’s instructions and detect them on a MAGPIX (Luminex)."
    },
    {
      "id": "S11",
      "title": "Statistical Analysis of Cytokines",
      "instruction": "Assess the significance of cytokine levels using the Mann–Whitney U test."
    },
    {
      "id": "S12",
      "title": "Statistical Analysis of Survival",
      "instruction": "Evaluate the significance of survival courses by comparing Kaplan-Meier curves using the log rank (Mantel-Cox) test."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Isolate Myofibers",
      "instruction": "Isolate healthy intact myofibers from extensor digitorum longus (EDL) muscles for subsequent experiments."
    },
    {
      "id": "S2",
      "title": "Mechanically Damage Myofibers",
      "instruction": "Use a Pasteur pipette to mechanically damage some of the isolated myofibers and confirm damage by observing shrunken morphology."
    },
    {
      "id": "S3",
      "title": "Co-Culture Myofibers",
      "instruction": "Co-culture intact myofibers with damaged myofibers to assess the effect of damaged myofibers on satellite cell activation."
    },
    {
      "id": "S4",
      "title": "Incubate Co-Culture",
      "instruction": "Incubate the co-culture for 48 to 72 hours to allow for satellite cell activation and proliferation assessment."
    },
    {
      "id": "S5",
      "title": "Perform Immunofluorescence",
      "instruction": "Conduct immunofluorescence analysis on the co-cultured myofibers to detect the presence of MYOD+ and Ki67+ satellite cells."
    },
    {
      "id": "S6",
      "title": "Wash and Replace Media",
      "instruction": "After co-culturing, wash out the damaged myofibers and replace the culture media with fresh DMEM for an additional 24 hours."
    },
    {
      "id": "S7",
      "title": "Analyze Cell States",
      "instruction": "Perform immunofluorescence analysis again to evaluate the proportions of PAX7+ MYOD- quiescent satellite cells after the media change."
    },
    {
      "id": "S8",
      "title": "Proteome Analysis",
      "instruction": "Conduct proteome analysis on the supernatant from intact and damaged myofiber cultures to identify potential DMDFs."
    },
    {
      "id": "S9",
      "title": "Prepare Recombinant Proteins",
      "instruction": "Prepare recombinant proteins of identified DMDFs (AK-1, CK, GAPDH, PGAM-2, TPI) for treatment of isolated myofibers."
    },
    {
      "id": "S10",
      "title": "Treat Myofibers with DMDFs",
      "instruction": "Treat isolated myofibers associated with satellite cells with the recombinant DMDF proteins in a floating culture condition for 72 hours."
    },
    {
      "id": "S11",
      "title": "Perform Immunostaining",
      "instruction": "Immunostain the treated myofibers to assess the activation of satellite cells by measuring PAX7+ MYOD+ and PAX7+ Ki67+ populations."
    },
    {
      "id": "S12",
      "title": "Control Treatments",
      "instruction": "Include PBS, BSA, and urease as control treatments to validate the specificity of the DMDF effects on satellite cell activation."
    },
    {
      "id": "S13",
      "title": "Analyze Results",
      "instruction": "Analyze the data from immunostaining to determine the effects of DMDFs on satellite cell activation and proliferation."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Obtain Ethical Approval",
      "instruction": "Secure ethical approval from the relevant committee (Leeds East REC 06/Q1206/180) before proceeding with any experiments."
    },
    {
      "id": "S2",
      "title": "Perform Laser Microdissection",
      "instruction": "Use a Zeiss/PALM Microscope to perform laser microdissection on formalin-fixed/paraffin-embedded tissue to isolate target cell types."
    },
    {
      "id": "S3",
      "title": "Stain Tissue Samples",
      "instruction": "Conduct SMA staining using mouse monoclonal antibody M851 at a dilution of 1:1000 with an IntelliPATH automated stainer."
    },
    {
      "id": "S4",
      "title": "Culture Cell Lines",
      "instruction": "Obtain MCF7 and HB2 cells from the European Collection of Cell Cultures and culture them under appropriate conditions."
    },
    {
      "id": "S5",
      "title": "Transfect Cells",
      "instruction": "Perform reverse transfection of pre-/anti-miR and/or plasmids using HiPerFect transfection reagent."
    },
    {
      "id": "S6",
      "title": "Establish Stable Cell Lines",
      "instruction": "Generate stable cell lines expressing GFP and firefly luciferase by using the respective expression vectors."
    },
    {
      "id": "S7",
      "title": "Isolate Primary Fibroblasts",
      "instruction": "Isolate primary fibroblasts from breast surgical samples and immortalize them using hTERT retroviral transduction."
    },
    {
      "id": "S8",
      "title": "Conduct Functional Assays",
      "instruction": "Perform assays for cell viability, cell cycle, apoptosis, migration, and invasion as previously described."
    },
    {
      "id": "S9",
      "title": "Perform Flow Cytometry",
      "instruction": "Use LSRII and MoFlo machines for flow cytometry and fluorescence-activated cell sorting, respectively."
    },
    {
      "id": "S10",
      "title": "Conduct Spheroid Invasion Assays",
      "instruction": "Carry out spheroid invasion assays and formalin-fix the spheroids for further analysis."
    },
    {
      "id": "S11",
      "title": "Extract RNA",
      "instruction": "Use RecoverAll Total Nucleic Acid Isolation for FFPE to extract RNA from formalin-fixed samples and MirVana miRNA Isolation for miRNA extraction from cell lines."
    },
    {
      "id": "S12",
      "title": "Perform qPCR",
      "instruction": "Conduct quantitative PCR analyses in triplicate using Taqman assays on 7500/7900HT machines."
    },
    {
      "id": "S13",
      "title": "Conduct Microarray Analysis",
      "instruction": "Perform microarray analyses of miRNA expression using human miRNA v2 arrays and system v1.7 reagents."
    },
    {
      "id": "S14",
      "title": "Analyze Protein Samples",
      "instruction": "Separate peptides from processed cell lysates by capillary liquid chromatography and analyze them using tandem mass spectrometry."
    },
    {
      "id": "S15",
      "title": "Perform Statistical Analyses",
      "instruction": "Analyze data using Prism for statistical tests and R for mass spectrometry data analysis, applying appropriate normalization and false discovery rate adjustments."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Sequence Analysis",
      "instruction": "Compile a database of protein sequences from 93 vertebrate TDP43 homologs, categorizing them into NTDs, RRM domains, and CTDs."
    },
    {
      "id": "S2",
      "title": "Calculate Edit Distance",
      "instruction": "Calculate the Levenshtein or edit distance normalized to a sequence length of 100 amino acids for each collection to assess sequence diversity."
    },
    {
      "id": "S3",
      "title": "Analyze Amino Acid Composition",
      "instruction": "Analyze the amino acid composition of the conserved region (CR) and the intrinsically disordered regions (IDRs) surrounding it, comparing them to the structured NTD and RRM domains."
    },
    {
      "id": "S4",
      "title": "Identify Hydrophobic Patterns",
      "instruction": "Examine the occurrence of hydrophobic residues in conserved intervals within the IDRs and calculate hydrophobicity using a sliding window approach."
    },
    {
      "id": "S5",
      "title": "Generate TDP43 RRM-GFP Reporter",
      "instruction": "Replace the RNA-binding RRM domains of TDP43 with GFP to create a reporter protein (TDP43 RRM-GFP) that forms micron-sized liquid droplets."
    },
    {
      "id": "S6",
      "title": "Transfect Cells",
      "instruction": "Transfect living cells with constructs expressing TDP43 RRM-GFP to analyze phase separation behavior."
    },
    {
      "id": "S7",
      "title": "Monitor Fluorescence",
      "instruction": "Use high-throughput automated confocal microscopy and flow cytometry to monitor nuclear and total GFP fluorescence in cells expressing TDP43 RRM-GFP."
    },
    {
      "id": "S8",
      "title": "Mutate CTD Sequences",
      "instruction": "Introduce systematic mutations in the CTD of TDP43 RRM-GFP to assess their effects on phase separation and splicing."
    },
    {
      "id": "S9",
      "title": "Assess Phase Separation",
      "instruction": "Evaluate the phase separation of TDP43 RRM-GFP droplets in cells with wild-type and mutant IDRs to determine the critical concentration for phase separation."
    },
    {
      "id": "S10",
      "title": "Purify Full-Length TDP43",
      "instruction": "Purify full-length TDP43 with wild-type and mutant CTDs from bacteria for in vitro phase separation analysis."
    },
    {
      "id": "S11",
      "title": "Test RNA Effects",
      "instruction": "Investigate the effect of RNA on the phase separation of purified TDP43 variants at varying concentrations."
    },
    {
      "id": "S12",
      "title": "Analyze Phase Separation Properties",
      "instruction": "Characterize the phase separation behavior of purified TDP43 variants to confirm findings from the TDP43 RRM-GFP reporter assay."
    },
    {
      "id": "S13",
      "title": "Evaluate Interaction Types",
      "instruction": "Use the live-cell reporter assay to assess the interactions (hydrophobic, π–π, and cation–π) that influence the material properties of TDP43 condensates."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Cell Culture",
      "instruction": "Culture human U2OS, A549, and mouse J774 cells in DMEM with 10% FBS, 2 mM L-glutamine, and 1% penicillin/streptomycin at 37°C in a humidified incubator with 5% CO2."
    },
    {
      "id": "S2",
      "title": "Transfection of 293-FT Cells",
      "instruction": "Co-transfect 6 µg of pBABED retroviral plasmids with 3.2 µg pCMV-gag-pol and 2.8 µg pCMV-VSV-G in 70% confluent 293-FT cells using a transfection solution prepared in Opti-MEM and PEI."
    },
    {
      "id": "S3",
      "title": "Medium Replacement",
      "instruction": "Replace the medium of the transfected 293-FT cells with fresh full medium 16 hours post-transfection."
    },
    {
      "id": "S4",
      "title": "Collection of Retroviruses",
      "instruction": "Collect the retroviruses from the growth medium 24 hours after transfection and filter using 0.45 µm filters."
    },
    {
      "id": "S5",
      "title": "Infection of Target Cells",
      "instruction": "Infect approximately 60% confluent target cells with the retroviral medium containing 8 µg/ml polybrene for 24 hours."
    },
    {
      "id": "S6",
      "title": "Selection of Infected Cells",
      "instruction": "Select cells that have integrated the retrovirus by treating them with 2 µg/ml puromycin."
    },
    {
      "id": "S7",
      "title": "Cell Lysis",
      "instruction": "Wash the cells twice with ice-cold PBS, scrape them in lysis buffer on ice, and clarify the cell extracts."
    },
    {
      "id": "S8",
      "title": "Immunoprecipitation",
      "instruction": "Incubate clarified lysates with anti-FLAG M2 resin overnight at 4°C on a rotating wheel."
    },
    {
      "id": "S9",
      "title": "Washing Resin",
      "instruction": "Wash the resin three times with lysis buffer to remove unbound proteins."
    },
    {
      "id": "S10",
      "title": "Elution of FLAG-Fusion Proteins",
      "instruction": "Elute FLAG-fusion proteins from the resin by boiling in SDS sample buffer for 5 minutes at 95°C."
    },
    {
      "id": "S11",
      "title": "SDS-PAGE",
      "instruction": "Separate the eluted proteins by electrophoresis on 8% SDS-PAGE gels."
    },
    {
      "id": "S12",
      "title": "Western Blotting",
      "instruction": "Transfer proteins onto PVDF or nitrocellulose membranes, block, and incubate with primary antibodies overnight at 4°C."
    },
    {
      "id": "S13",
      "title": "Detection",
      "instruction": "Wash membranes and incubate with HRP-conjugated secondary antibodies, followed by detection using ECL reagent."
    },
    {
      "id": "S14",
      "title": "siRNA Transfection",
      "instruction": "Transfect cells with 20 nM siRNA using Lipofectamine RNAiMAX and replace the medium with fresh growth medium after 16 hours."
    },
    {
      "id": "S15",
      "title": "RNA Isolation and cDNA Synthesis",
      "instruction": "Harvest cells, isolate RNA, and perform cDNA synthesis and RT-PCR according to the manufacturer's guidelines."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Fly Preparation",
      "instruction": "Obtain Drosophila melanogaster strains, including TBPH-null alleles (tbph Δ23 and tbph Δ142) and wild-type controls."
    },
    {
      "id": "S2",
      "title": "mRNA Isolation",
      "instruction": "Isolate mRNAs from the adult heads of TBPH-null and wild-type flies for subsequent analysis."
    },
    {
      "id": "S3",
      "title": "Microarray Hybridization",
      "instruction": "Hybridize the isolated mRNAs to GeneChip Drosophila Genome 2.0 Arrays to analyze gene expression patterns."
    },
    {
      "id": "S4",
      "title": "Statistical Analysis",
      "instruction": "Perform statistical analysis on the microarray data to identify dysregulated transposons in TBPH-null alleles."
    },
    {
      "id": "S5",
      "title": "qRT-PCR Confirmation",
      "instruction": "Conduct quantitative RT-PCR (qRT-PCR) using specific primers to confirm the microarray findings regarding transposon expression."
    },
    {
      "id": "S6",
      "title": "NRTI Treatment",
      "instruction": "Administer nucleoside and non-nucleoside reverse transcriptase inhibitors (NRTIs and NNRTIs) to TBPH-null flies to assess their effects on locomotive defects."
    },
    {
      "id": "S7",
      "title": "RNAi Constructs Preparation",
      "instruction": "Prepare transgenic flies carrying RNAi constructs against the endogenous mRNA sequence of gypsy for silencing experiments."
    },
    {
      "id": "S8",
      "title": "Neuronal Expression of RNAi",
      "instruction": "Express the RNAi constructs in neurons using the pan-neuronal driver elav-GAL4 or the motoneuronal promoter D42-GAL4."
    },
    {
      "id": "S9",
      "title": "Phenotype Assessment",
      "instruction": "Evaluate the locomotive phenotypes of TBPH-null larvae expressing RNAi against gypsy compared to controls expressing RNAi against GFP."
    },
    {
      "id": "S10",
      "title": "Dicer-2 Expression Analysis",
      "instruction": "Analyze the expression levels of Dicer-2 and other components of the siRNA machinery in TBPH-null and wild-type flies using qRT-PCR."
    },
    {
      "id": "S11",
      "title": "Pull-Down Assays",
      "instruction": "Perform pull-down assays to investigate the interaction between TBPH and Dicer-2 in Drosophila neurons."
    },
    {
      "id": "S12",
      "title": "UAS-Dcr-2 Expression",
      "instruction": "Cross transgenic flies containing UAS-Dcr-2 with flies carrying the elav-GAL4 or D42-GAL4 drivers to recover Dcr-2 expression in neurons."
    },
    {
      "id": "S13",
      "title": "Locomotion Recovery Assessment",
      "instruction": "Assess the recovery of locomotive abilities in TBPH-null larvae expressing UAS-Dcr-2 compared to those expressing UAS-GFP."
    },
    {
      "id": "S14",
      "title": "Synaptic Growth Analysis",
      "instruction": "Examine the growth of motoneuron synaptic terminals and the innervation of muscles in TBPH-null flies expressing Dcr-2."
    },
    {
      "id": "S15",
      "title": "Glial Cell Expression of Dcr-2",
      "instruction": "Express Dcr-2 in glial cells using repo-GAL4 and evaluate its effects on locomotive deficiencies in TBPH-null flies."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Animal Preparation",
      "instruction": "Obtain male albino Wistar rats weighing between 250 to 270 g and maintain them at a constant room temperature of 22°C ± 1°C with 60% relative humidity on a 12:12-hour light-dark cycle."
    },
    {
      "id": "S2",
      "title": "Anesthesia and Surgery Setup",
      "instruction": "Anaesthetize the rats with chloral hydrate at a dose of 400 mg/kg and position them in a stereotaxic apparatus according to the brain atlas of Paxinos and Watson."
    },
    {
      "id": "S3",
      "title": "Injection of Treatments",
      "instruction": "Administer a single intranigral injection of either 2 μl of vehicle or 2 μg of LPS into the left SN of the rats, depending on the treatment group, 2 hours after the application of the first stressor."
    },
    {
      "id": "S4",
      "title": "Stress Application",
      "instruction": "Implement a 9-day variate stressor paradigm for the stressed groups, ensuring that the application of stressors occurs at different times each day to minimize predictability."
    },
    {
      "id": "S5",
      "title": "Body Weight Measurement",
      "instruction": "Measure the body weight of the rats at the beginning and the end of the 10-day treatment period to evaluate HPA axis activation."
    },
    {
      "id": "S6",
      "title": "Blood Collection",
      "instruction": "After the treatment period, deeply anaesthetize the rats and collect blood from the heart for serum corticosterone measurement."
    },
    {
      "id": "S7",
      "title": "Immunohistochemistry Preparation",
      "instruction": "Prepare 20-μm coronal sections of the brain on a cryostat at -15°C and mount them on gelatine-coated slides for immunohistological evaluation."
    },
    {
      "id": "S8",
      "title": "Antibody Incubation",
      "instruction": "Incubate the sections with primary antibodies diluted in TBS containing serum and Triton X-100 for 24 hours at room temperature."
    },
    {
      "id": "S9",
      "title": "Secondary Antibody Incubation",
      "instruction": "After rinsing, incubate the sections with biotinylated secondary antibodies for 2 hours, followed by incubation with ExtrAvidin-Peroxidase solution."
    },
    {
      "id": "S10",
      "title": "Visualization of Peroxidase",
      "instruction": "Visualize the peroxidase activity by performing a standard diaminobenzidine-hydrogen peroxide reaction for 5 minutes."
    },
    {
      "id": "S11",
      "title": "Data Analysis",
      "instruction": "Analyze the immunohistochemical data by counting the number of positive cells and measuring areas lacking GFAP immunoreactivity using imaging software."
    },
    {
      "id": "S12",
      "title": "RNA Extraction",
      "instruction": "Dissect the left SN from each rat, snap-freeze in liquid nitrogen, and extract total RNA using the RNeasy kit."
    },
    {
      "id": "S13",
      "title": "cDNA Synthesis",
      "instruction": "Synthesize cDNA from 1 μg of total RNA using the QuantiTect Reverse Transcription Kit according to the manufacturer's instructions."
    },
    {
      "id": "S14",
      "title": "Real-Time PCR",
      "instruction": "Perform real-time PCR using iQ SYBR Green Supermix and specific primers, following the thermal cycling conditions provided."
    },
    {
      "id": "S15",
      "title": "Melting Curve Analysis",
      "instruction": "Conduct melting curve analysis to confirm the presence of a single PCR product at the predicted melting temperature."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Obtain Arabidopsis Accessions",
      "instruction": "Acquire Arabidopsis accessions from the Nottingham Arabidopsis Stock Centre and other specified sources."
    },
    {
      "id": "S2",
      "title": "Generate HaRxL62 Construct",
      "instruction": "Recombine the corresponding ORF from the signal peptide cleavage site into the Gateway destination binary vector under the control of the Cauliflower mosaic virus 35S promoter."
    },
    {
      "id": "S3",
      "title": "Transform Agrobacterium",
      "instruction": "Transfer the construct into Agrobacterium tumefaciens strain GV3101 (pMP90 RK)."
    },
    {
      "id": "S4",
      "title": "Transform Arabidopsis",
      "instruction": "Transform Arabidopsis accession Col-0 using the floral dipping method with the Agrobacterium containing the HaRxL62 construct."
    },
    {
      "id": "S5",
      "title": "Select Primary Transformants",
      "instruction": "Select primary transformants (T1) on soil containing BASTA and verify expression of HaRxL62 by Western blot analysis."
    },
    {
      "id": "S6",
      "title": "Observe T2 Progeny",
      "instruction": "Observe the progeny of the T2 generation for 3:1 (BASTA-resistant/BASTA-susceptible) segregation."
    },
    {
      "id": "S7",
      "title": "Select Homozygous Lines",
      "instruction": "Select homozygous lines by examining the BASTA resistance of T3 seedlings."
    },
    {
      "id": "S8",
      "title": "Grow Arabidopsis Plants",
      "instruction": "Grow Arabidopsis plants at 22°C and 60% humidity under a 10-h photoperiod and a 14-h dark period in controlled growth cabinets."
    },
    {
      "id": "S9",
      "title": "Inoculate with Hpa",
      "instruction": "Spray-inoculate Arabidopsis plants with a spore suspension of 5×10^4 conidiospores/ml and cover with a transparent lid to maintain high humidity."
    },
    {
      "id": "S10",
      "title": "Stain Leaves",
      "instruction": "Stain leaves inoculated with Hpa using trypan blue to evaluate hyphae growth and HR cell death."
    },
    {
      "id": "S11",
      "title": "Harvest Plants for Conidiospores",
      "instruction": "Harvest 5 pools of 3 plants for each Arabidopsis line in 1 ml of water and determine the amount of conidiospores released using a haemocytometer."
    },
    {
      "id": "S12",
      "title": "Extract Total RNA",
      "instruction": "Extract total RNAs using TRI reagent and 1-bromo-3-chloropropane, followed by precipitation and purification."
    },
    {
      "id": "S13",
      "title": "Synthesize cDNA",
      "instruction": "Use 3 µg of total RNA to generate cDNAs in a 20 µl reaction volume according to the Superscript II Reverse Transcriptase protocol."
    },
    {
      "id": "S14",
      "title": "Perform qPCR",
      "instruction": "Run qPCR in a 10 µl final volume using SYBR Green mix, diluted cDNAs, and primers, following the specified thermal cycling program."
    },
    {
      "id": "S15",
      "title": "Analyze qPCR Data",
      "instruction": "Determine relative expression values using EF-1α as a reference gene and the comparative cycle threshold method."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Vaccination of Mice",
      "instruction": "Vaccinate BALB/c mice twice at 6–7 week intervals with VRP-SARS-N or control VRP-GFP via intranasal or subcutaneous routes."
    },
    {
      "id": "S2",
      "title": "Challenge with SARS-CoV",
      "instruction": "After vaccination, challenge the mice with mouse-adapted SARS-CoV at varying doses ranging from 100 to 10,000 PFUs."
    },
    {
      "id": "S3",
      "title": "Assessment of CD4+ T Cell Response",
      "instruction": "Evaluate the CD4+ T cell response in the lungs and airways of the vaccinated mice to determine the specificity and localization of the response."
    },
    {
      "id": "S4",
      "title": "Depletion of Memory CD4+ T Cells",
      "instruction": "Systemically deplete memory CD4+ T cells in vaccinated mice two days prior to challenge to assess their role in protection."
    },
    {
      "id": "S5",
      "title": "Replenishment of CD4+ T Cells",
      "instruction": "Treat vaccinated mice with CD4+ T-cell-depleting antibody 98 days prior to challenge to confirm the importance of memory CD4+ T cells."
    },
    {
      "id": "S6",
      "title": "Analysis of Cytokine Expression",
      "instruction": "Measure IFN-γ mRNA levels in the lungs of VRP-SARS-N-immunized mice at day 1 post-infection to evaluate the immune response."
    },
    {
      "id": "S7",
      "title": "In Vivo Cytokine Expression Assay",
      "instruction": "Administer Brefeldin A to mice for 6 hours prior to ex vivo analysis to confirm IFN-γ expression by airway CD4+ T cells."
    },
    {
      "id": "S8",
      "title": "Neutralization of IFN-γ",
      "instruction": "Neutralize IFN-γ in the airway prior to infection and every two days thereafter to assess its role in the immune response and protection."
    },
    {
      "id": "S9",
      "title": "Evaluation of Dendritic Cell Migration",
      "instruction": "Assess the migration of respiratory dendritic cells to mediastinal lymph nodes to determine the impact of airway CD4+ T cells on CD8+ T cell priming."
    },
    {
      "id": "S10",
      "title": "Histological Analysis",
      "instruction": "Perform histological analysis on lung tissues from challenged mice to evaluate pathological changes and correlate with immune responses."
    },
    {
      "id": "S11",
      "title": "Functional Assays of T Cells",
      "instruction": "Conduct functional assays to evaluate the effector functions of airway N-specific CD4+ T cells post-challenge."
    },
    {
      "id": "S12",
      "title": "Longitudinal Monitoring of T Cell Populations",
      "instruction": "Monitor the dynamics of N-specific CD4+ T cell populations over time after vaccination and challenge to assess memory and functional persistence."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Synchronized Egg Isolation",
      "instruction": "Synchronize C. elegans by treating gravid adults with alkaline hypochlorite to isolate eggs."
    },
    {
      "id": "S2",
      "title": "Construct Repair Template",
      "instruction": "Use SapTrap to construct the 30xlinker::GFP^SEC^TEV::AID degron::3xFLAG repair template (pJW1747) for knock-in into the nhr-25 gene."
    },
    {
      "id": "S3",
      "title": "Prepare Competent Cells",
      "instruction": "Generate DH10β competent E. coli cells in-house for plasmid generation."
    },
    {
      "id": "S4",
      "title": "Assemble Repair Template",
      "instruction": "Assemble the final repair template using pDD379, annealed oligos, pJW1779, 3′ homology arm PCR product, pJW1347, pDD372, pDD363, and pJW1759."
    },
    {
      "id": "S5",
      "title": "Purify Repair Template",
      "instruction": "Purify the pJW1747 repair template using the Invitrogen PureLink HQ Mini Plasmid DNA Purification Kit, including the optional wash step."
    },
    {
      "id": "S6",
      "title": "Prepare Injection Mix",
      "instruction": "Prepare the injection mix containing 10 ng/µL of pJW1747, 50 ng/µL of pDD121, and co-injection markers."
    },
    {
      "id": "S7",
      "title": "Inject Animals",
      "instruction": "Inject N2 animals with the prepared injection mix to generate knock-ins."
    },
    {
      "id": "S8",
      "title": "Verify Knock-ins",
      "instruction": "Verify each knock-in junction via PCR using specific primers."
    },
    {
      "id": "S9",
      "title": "Backcross Knock-ins",
      "instruction": "Backcross the verified knock-ins five times against wild-type N2 animals to produce JDW58."
    },
    {
      "id": "S10",
      "title": "Excise SEC",
      "instruction": "Excise the SEC from JDW58 by heat-shock to produce JDW59."
    },
    {
      "id": "S11",
      "title": "Cross Strains",
      "instruction": "Cross JDW58 with CA1200 to generate JDW70, then excise the SEC to produce JDW71."
    },
    {
      "id": "S12",
      "title": "Prepare Auxin Solutions",
      "instruction": "Prepare 250 mM stock solutions of IAA and NAA in ethanol, and K-NAA in deionized water for auxin experiments."
    },
    {
      "id": "S13",
      "title": "Transfer Larvae to Plates",
      "instruction": "Transfer synchronized L1 larval stage animals to NGM agar plates seeded with E. coli OP50."
    },
    {
      "id": "S14",
      "title": "Conduct Auxin Treatment",
      "instruction": "Transfer animals to plates treated with IAA, NAA, or K-NAA at the P6.p 2-cell stage."
    },
    {
      "id": "S15",
      "title": "Score Developmental Phenotypes",
      "instruction": "Score for anchor cell specification and vulval precursor cell arrest using DIC optics after appropriate growth periods."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Plasmid Construction",
      "instruction": "Construct the pCRISPR-SacB-gDNA plasmids encoding the gRNAs targeting the genes of interest."
    },
    {
      "id": "S2",
      "title": "Transformation of E. coli",
      "instruction": "Transform E. coli BL21(DE3)ΔompA (pCasRed) with the constructed pCRISPR-SacB-gDNA plasmids."
    },
    {
      "id": "S3",
      "title": "Colony Selection",
      "instruction": "Select colonies on LB plates supplemented with chloramphenicol and kanamycin to ensure successful transformation."
    },
    {
      "id": "S4",
      "title": "Colony Counting",
      "instruction": "Count the number of colonies to assess the transformation efficiency of the pCRISPR-SacB-gDNA plasmids."
    },
    {
      "id": "S5",
      "title": "Design of Donor DNA",
      "instruction": "Design 70 bp single-stranded donor DNAs (ss-dDNAs) to delete 30 bp and introduce a premature stop codon in each target gene."
    },
    {
      "id": "S6",
      "title": "Transformation with Donor DNA",
      "instruction": "Transform E. coli BL21(DE3)ΔompA (pCasRed) with the pCRISPR-SacB-gDNA plasmids and their corresponding ss-dDNAs."
    },
    {
      "id": "S7",
      "title": "Random Colony Selection",
      "instruction": "From each transformation, randomly select ten colonies for analysis to identify successful mutations."
    },
    {
      "id": "S8",
      "title": "PCR Analysis",
      "instruction": "Perform PCR on the selected colonies to identify those carrying the desired 30 bp deletion."
    },
    {
      "id": "S9",
      "title": "Mutation Efficiency Assessment",
      "instruction": "Establish the success rate of mutagenesis by calculating the percentage of colonies with the desired mutation."
    },
    {
      "id": "S10",
      "title": "Selection of Functional gDNAs",
      "instruction": "Identify and select functional gDNAs that promote Cas9 cleavage based on transformation efficiency results."
    },
    {
      "id": "S11",
      "title": "Optimization of dDNA Conditions",
      "instruction": "Test different lengths and concentrations of dDNAs to optimize conditions for gene knockout."
    },
    {
      "id": "S12",
      "title": "Analysis of Mutation Outcomes",
      "instruction": "Analyze the outcomes of mutations to confirm successful gene inactivation and assess the robustness of the method."
    },
    {
      "id": "S13",
      "title": "Documentation of Results",
      "instruction": "Document the results of the experiments, including transformation efficiencies and mutation success rates."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Mouse Purchase",
      "instruction": "Purchase C57BL/6J male mice from the Jackson Laboratory."
    },
    {
      "id": "S2",
      "title": "Genetic Cross",
      "instruction": "Generate CX3CR1+/GFP/CCR2+/RFP animals by crossing CX3CR1GFP/GFP/CCR2RFP/RFP with C57BL/6J mice."
    },
    {
      "id": "S3",
      "title": "Chow Treatment",
      "instruction": "Starting at 8 weeks old, treat C57BL/6J mice with PLX5622 or control chow for 21 days."
    },
    {
      "id": "S4",
      "title": "Irradiation Setup",
      "instruction": "Anesthetize mice with an intraperitoneal injection of ketamine and xylazine, then place them 16.3 cm from a cesium-137 source."
    },
    {
      "id": "S5",
      "title": "Radiation Treatment",
      "instruction": "Deliver 1.65 Gy of irradiation on both sides of the head every other day for a total of 10 Gy over 5 days."
    },
    {
      "id": "S6",
      "title": "NOR Test Habituation",
      "instruction": "House mice in a room with a reversed light cycle for at least 2 weeks, handling them for 5 minutes each day for 5 days before testing."
    },
    {
      "id": "S7",
      "title": "NOR Test Exploration",
      "instruction": "Allow mice to explore an open arena for 10 minutes for two consecutive days, then conduct the NOR test with two identical objects on day 3."
    },
    {
      "id": "S8",
      "title": "NOR Test Novel Object",
      "instruction": "On day 4, replace one identical object with a novel object and allow mice to explore for 5 minutes."
    },
    {
      "id": "S9",
      "title": "Euthanize Mice",
      "instruction": "Euthanize mice used for Golgi staining at the end of the first NOR test and perfuse with ice-cold PBS."
    },
    {
      "id": "S10",
      "title": "Flow Cytometry Sample Preparation",
      "instruction": "For flow cytometry, euthanize mice at the indicated time relative to the last day of fWBI and prepare brain samples."
    },
    {
      "id": "S11",
      "title": "Golgi Staining",
      "instruction": "Place brain hemispheres in Golgi staining solution for 14 days, then transfer to 30% sucrose solution overnight at 4 °C."
    },
    {
      "id": "S12",
      "title": "Brain Sectioning",
      "instruction": "Cut brains into 100 μm sections with a vibratome, mount on slides, and dry for 2 days."
    },
    {
      "id": "S13",
      "title": "Data Collection",
      "instruction": "Take images of stained samples using a Keyence 7000 system and analyze dendritic spine density."
    },
    {
      "id": "S14",
      "title": "Statistical Analysis",
      "instruction": "Analyze data from the NOR test, DMP test, and flow cytometry using appropriate statistical methods."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Worm Culture",
      "instruction": "Grow and maintain worm strains on nematode growth media (NGM) plates seeded with Escherichia coli (OP50) at 20°C."
    },
    {
      "id": "S2",
      "title": "Strain Preparation",
      "instruction": "Prepare the required worm strains by crossing and creating mutants as described in the protocol."
    },
    {
      "id": "S3",
      "title": "Temperature Adjustment",
      "instruction": "To induce de-silencing of the pie-1p::GFP(lap)::rpa-1 strain, grow the strain for 1-2 generations at 25°C followed by one generation at 20°C."
    },
    {
      "id": "S4",
      "title": "Microirradiation Setup",
      "instruction": "Locate nuclei in the germline and focus the Z-plane on the center of the target nuclei before microirradiation."
    },
    {
      "id": "S5",
      "title": "Microirradiation",
      "instruction": "Microirradiate the target nuclei using a single pulse from a 365nm pulsed laser, adjusting the intensity as specified."
    },
    {
      "id": "S6",
      "title": "Live Imaging Preparation",
      "instruction": "Position worms for live imaging on a 3% agarose pad or in a live imaging petri dish, ensuring they are in M9 and polystyrene beads."
    },
    {
      "id": "S7",
      "title": "Live Imaging",
      "instruction": "Acquire images of live worms at 2-minute intervals, focusing on the microirradiated nuclei and adjusting the Z-stack as necessary."
    },
    {
      "id": "S8",
      "title": "Image Processing",
      "instruction": "Process the acquired image stacks in MetaMorph to create maximum projections for each time point."
    },
    {
      "id": "S9",
      "title": "Foci Scoring",
      "instruction": "Score the number of foci in each nucleus at every time point using FIJI-ImageJ, recording new foci that appear post-microirradiation."
    },
    {
      "id": "S10",
      "title": "Worm Recovery",
      "instruction": "Recover microirradiated worms by submerging the slide in M9 and gently prying off the coverslip, then transferring worms to NGM plates seeded with OP50."
    },
    {
      "id": "S11",
      "title": "Gonad Dissection",
      "instruction": "Dissect the recovered worms to extract their gonads for further analysis."
    },
    {
      "id": "S12",
      "title": "Immunofluorescent Staining",
      "instruction": "Fix and stain the extracted gonads with primary and secondary antibodies as specified in the protocol."
    },
    {
      "id": "S13",
      "title": "Distance Measurement",
      "instruction": "Use the straight line measurement tool in FIJI-ImageJ to measure distances in μm between foci within mid-pachytene nuclei."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Animal Acquisition",
      "instruction": "Obtain male 3-month old BALB/cARC and C57BL/6JARC mice from the Animal Resources Centre and house them in groups of four in individually ventilated cages."
    },
    {
      "id": "S2",
      "title": "Environmental Setup",
      "instruction": "Maintain the housing environment at 21 ± 1°C and 50 ± 10% humidity with a 12-hour light cycle, marking individual tails for identification."
    },
    {
      "id": "S3",
      "title": "Food Restriction",
      "instruction": "Food-restrict mice to 90% of their free-feeding body weight by adjusting daily food amounts, ensuring all mice can consume without fighting."
    },
    {
      "id": "S4",
      "title": "Habituation to Testing Room",
      "instruction": "Bring the home cage of mice into the testing room for a minimum of 30 minutes prior to each training session."
    },
    {
      "id": "S5",
      "title": "Touchscreen Setup",
      "instruction": "Set up the operant chambers with touchscreens, reward dispensers, and clean all surfaces with 70% ethanol between animals."
    },
    {
      "id": "S6",
      "title": "Reward Acclimation",
      "instruction": "Provide a small quantity of strawberry milk in a falcon tube lid in the home cage for 3 days to acclimate mice to the liquid reward."
    },
    {
      "id": "S7",
      "title": "Training - Habituation Stage",
      "instruction": "Train mice to collect a reward when the tray illuminates, requiring them to complete 50 trials within 20 minutes over two consecutive sessions."
    },
    {
      "id": "S8",
      "title": "Training - Initial Touch Stage",
      "instruction": "Mice learn to touch a white square on the screen to receive a 3× reward or a single reward after 30 seconds of inactivity, progressing after 100 trials."
    },
    {
      "id": "S9",
      "title": "Training - Must Touch Stimuli Stage",
      "instruction": "Require mice to touch the stimuli to receive a reward, completing 100 trials in under 30 minutes to progress."
    },
    {
      "id": "S10",
      "title": "Training - Must Initiate Stage",
      "instruction": "Mice must enter the reward tray to start trials, completing 100 trials in 60 minutes to advance."
    },
    {
      "id": "S11",
      "title": "Training - Punish Incorrect Stage",
      "instruction": "Implement a time-out for incorrect touches, requiring 100 trials in under 60 minutes with at least 70% correct responses."
    },
    {
      "id": "S12",
      "title": "Visual Discrimination Task",
      "instruction": "Conduct the VD task where mice discriminate between two visual stimuli, requiring 100 trials in under 60 minutes with at least 80% correct."
    },
    {
      "id": "S13",
      "title": "Reversal Task",
      "instruction": "Switch the reward contingency for the reversal task, requiring mice to learn the new pairing until reaching 80% correct or a maximum of 20 sessions."
    },
    {
      "id": "S14",
      "title": "Data Collection",
      "instruction": "Collect data on trials completed, session duration, response types, and other measures during touchscreen testing."
    },
    {
      "id": "S15",
      "title": "Behavioral Testing",
      "instruction": "Conduct additional behavioral tests such as the Open Field and Forced Swim Test to measure locomotor activity and behavioral despair."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Cell Culture",
      "instruction": "Maintain DT40, Non-KI(B), KI(B), and KI(MΦ) cell lines as previously described."
    },
    {
      "id": "S2",
      "title": "Prepare gRNA Complex",
      "instruction": "Use the complex of CRISPR RNA (crRNA) targeting the Pax5 promoter and trans-activating crRNA (tracrRNA) as Pax5 gRNA for in vitro enChIP."
    },
    {
      "id": "S3",
      "title": "Fragment Chromatin DNA",
      "instruction": "Fragment chromatin DNA to an average length of about 2 kbp for subsequent isolation of target regions."
    },
    {
      "id": "S4",
      "title": "Perform iChIP or enChIP",
      "instruction": "Isolate the target region using either the iChIP procedure for Non-KI(B), KI(B), and KI(MΦ) or the in vitro enChIP procedure for DT40."
    },
    {
      "id": "S5",
      "title": "Purify DNA",
      "instruction": "Purify the isolated DNA from the iChIP or enChIP procedure."
    },
    {
      "id": "S6",
      "title": "Prepare DNA Libraries",
      "instruction": "Use the TruSeq ChIP Sample Prep Kit (Illumina) to prepare DNA libraries, concentrating fragments around 0.4 kbp in length."
    },
    {
      "id": "S7",
      "title": "Sequence DNA Libraries",
      "instruction": "Subject the prepared DNA libraries to sequencing using the HiSeq platform according to the manufacturer's protocol."
    },
    {
      "id": "S8",
      "title": "Transfect DT40 Cells",
      "instruction": "Transfect DT40 cells (1 × 10^7) with 120 µg of Cas9 expression plasmid, 120 µg of sgRNA expression plasmids, and 0.3 µg of pEGFP-N3 using electroporation."
    },
    {
      "id": "S9",
      "title": "Sort GFP-positive Cells",
      "instruction": "One day after transfection, sort and expand the GFP-positive cells individually."
    },
    {
      "id": "S10",
      "title": "Extract Genomic DNA",
      "instruction": "Extract genomic DNA from the sorted cells to confirm targeted locus deletion."
    },
    {
      "id": "S11",
      "title": "Perform Genotyping PCR",
      "instruction": "Subject the extracted genomic DNA to genotyping PCR using KOD FX with specified cycling conditions."
    },
    {
      "id": "S12",
      "title": "Extract Total RNA",
      "instruction": "Extract total RNA from the cells as previously described."
    },
    {
      "id": "S13",
      "title": "Perform Quantitative RT-PCR",
      "instruction": "Conduct quantitative RT-PCR on the extracted RNA using appropriate primers."
    },
    {
      "id": "S14",
      "title": "Perform ChIP Assays",
      "instruction": "Use antibodies against H3K4me1, H3K27ac, and histone H3 to perform ChIP assays with DT40 cells."
    },
    {
      "id": "S15",
      "title": "Analyze ChIP DNA",
      "instruction": "Purify the ChIP DNA and use it as a template for real-time PCR with SYBR Select Master Mix."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Mouse Housing",
      "instruction": "Group house C57BL/6 mice (8 weeks old, 18–22 g) under controlled temperature (25°C) and a 12:12 light-dark cycle with unrestricted access to standard chow and water."
    },
    {
      "id": "S2",
      "title": "DSS Treatment",
      "instruction": "Dilute DSS (40,000 Da, 3% wt/vol) in drinking water and provide it to the mice for 7 days."
    },
    {
      "id": "S3",
      "title": "Euthanasia",
      "instruction": "After 7 days of DSS treatment, sacrifice the mice using CO2 euthanasia."
    },
    {
      "id": "S4",
      "title": "Tissue Collection",
      "instruction": "Collect a small piece (50 mg) of proximal colon from each mouse for RNA extraction."
    },
    {
      "id": "S5",
      "title": "RNA Extraction",
      "instruction": "Isolate total RNA from the colonic tissues using TRIzol according to the manufacturer's instructions."
    },
    {
      "id": "S6",
      "title": "Lithium Chloride Purification",
      "instruction": "Incubate RNA with 0.1 volume of 8 M LiCl on ice for 2 hours, then centrifuge at 14,000 g for 30 minutes at 4°C. Repeat the incubation and centrifugation."
    },
    {
      "id": "S7",
      "title": "RNA Precipitation",
      "instruction": "Precipitate RNA by adding 0.1 volume of 3 M sodium acetate and 2 volumes of absolute ethanol, then centrifuge at 14,000 g for 30 minutes at 4°C."
    },
    {
      "id": "S8",
      "title": "RNA Washing",
      "instruction": "Wash the RNA pellet with 100 μL of 70% ethanol and centrifuge at 14,000 g for 10 minutes at 4°C."
    },
    {
      "id": "S9",
      "title": "RNA Resuspension",
      "instruction": "Dissolve the RNA pellet in 20–50 μL of RNase-free water."
    },
    {
      "id": "S10",
      "title": "cDNA Synthesis",
      "instruction": "Synthesize cDNA using the Maxima First-Strand cDNA Synthesis Kit according to the manufacturer's instructions."
    },
    {
      "id": "S11",
      "title": "qPCR Setup",
      "instruction": "Quantify the expression of total RNA by performing qPCR using Maxima SYBR Green/ROX qPCR Master Mix in a Realplex Thermal Cycler."
    },
    {
      "id": "S12",
      "title": "Polymerase Activity Assay",
      "instruction": "Measure the enzymatic activity of Taq DNA polymerase using the EvaEZ™ Fluorometric Polymerase Activity Assay kit, incubating with water or DSS."
    },
    {
      "id": "S13",
      "title": "Reverse Transcriptase Assay",
      "instruction": "Measure the reverse transcriptase activity using the EnzChek Reverse Transcriptase Assay kit, incubating with water or DSS."
    },
    {
      "id": "S14",
      "title": "Surface Plasmon Resonance (SPR)",
      "instruction": "Perform SPR experiments by coupling a gold sensor chip with reverse transcriptase and passing primed RNA over the chip to assess binding."
    },
    {
      "id": "S15",
      "title": "Statistical Analysis",
      "instruction": "Analyze the data using an unpaired two-tailed t-test with GraphPad Prism 5 software, considering p < 0.05 as statistically significant."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Cell Isolation",
      "instruction": "Obtain plasma cells from the synovial fluid of a patient with anti-CCP-positive RA and isolate antibody-secreting cells from synovial fluid mononuclear cells using the fluorescent foci method."
    },
    {
      "id": "S2",
      "title": "B Cell Sorting",
      "instruction": "Sort single citrulline-specific B cells from the peripheral blood of other RA patients using an antigen-tetramer system via flow cytometry."
    },
    {
      "id": "S3",
      "title": "Peptide ELISA Setup",
      "instruction": "Prepare peptide ELISAs to assess binding to citrulline-containing and arginine-containing peptides, including specific proteins like filaggrin and vimentin."
    },
    {
      "id": "S4",
      "title": "mAb Dilution for ELISA",
      "instruction": "Dilute monoclonal antibodies (mAb) to a concentration of 5 μg/ml, then further dilute down to 0.15 ng/ml for use in the ELISA."
    },
    {
      "id": "S5",
      "title": "Full-Length Protein ELISA Setup",
      "instruction": "Dilute 10 μg/ml of fibrinogen, recombinant vimentin, and histone H4 in phosphate buffered saline (PBS) and coat Nunc Maxisorp 96-well plates."
    },
    {
      "id": "S6",
      "title": "Blocking Plates",
      "instruction": "Block the coated plates with 5% milk powder in PBS and incubate for 3 hours at 37°C with citrullination buffer or buffer control."
    },
    {
      "id": "S7",
      "title": "ACPA Incubation",
      "instruction": "Incubate the plates with ACPAs at a concentration of 5 μg/ml, diluted down to 0.15 ng/ml."
    },
    {
      "id": "S8",
      "title": "Secondary Antibody Incubation",
      "instruction": "Perform sequential incubation with secondary Fc-specific HRP-conjugated anti-human IgG or biotin-conjugated human IgG1-Fc plus HRP-conjugated streptavidin."
    },
    {
      "id": "S9",
      "title": "Development of ELISA",
      "instruction": "Develop the ELISA with SeramunBlau fast TMB and read the results using a Spectra Fluor."
    },
    {
      "id": "S10",
      "title": "Microarray Peptide Synthesis",
      "instruction": "Synthesize peptides that cover all arginine and lysine sites of extracellular matrix proteins and RA-related proteins, resulting in a total of 172,765 unique peptides."
    },
    {
      "id": "S11",
      "title": "mAb Dilution for Microarray",
      "instruction": "Dilute mAb to a concentration of 1 μg/ml, except for mAb 1325:07E07, which should be diluted to 0.55 μg/ml."
    },
    {
      "id": "S12",
      "title": "Scanning for Reactivity",
      "instruction": "Scan for citrulline and homocitrulline reactivity with each mAb at a resolution of 2 μm using a NimbleGen MS200 Scanner."
    },
    {
      "id": "S13",
      "title": "Western Blot Preparation",
      "instruction": "Solubilize full-length proteins in 8 M urea at 1 mg/ml, then electrophorese 10 μg on 12.5% SDS-PAGE gels and blot onto a nitrocellulose membrane."
    },
    {
      "id": "S14",
      "title": "Western Blot Incubation",
      "instruction": "Incubate the blots overnight at 37°C in citrullination buffer with hPAD2 or buffer control, followed by incubation with ACPAs."
    },
    {
      "id": "S15",
      "title": "Visualization of Western Blots",
      "instruction": "Perform visualization of the blots using Amersham Hyperfilm."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Cell Culture",
      "instruction": "Culture cells in DMEM supplemented with 10% fetal bovine serum (S+ medium) at 37°C and 5% CO2. Optionally, use different serum-free formulations as specified."
    },
    {
      "id": "S2",
      "title": "Add Ribonuclease Inhibitor",
      "instruction": "In selected experiments, add recombinant ribonuclease inhibitor (RI) at a final concentration of 4–8 U/ml either during medium renewal or after collecting cell-conditioned media."
    },
    {
      "id": "S3",
      "title": "Ultracentrifugation",
      "instruction": "Centrifuge the cell-conditioned medium that has been previously spun at 2000 × g for 2.5 hours at 100,000 × g and 4°C using an ultracentrifuge."
    },
    {
      "id": "S4",
      "title": "Concentrate Supernatant",
      "instruction": "Concentrate the supernatant to approximately 250 μl using 10,000 MWCO ultrafiltration units."
    },
    {
      "id": "S5",
      "title": "Size-Exclusion Chromatography",
      "instruction": "Dilute the concentrated supernatant with PBS to remove phenol red and small molecules, then inject 500 μl into a Superdex S200 10/300 column and perform size-exclusion chromatography at 0.9 ml/min."
    },
    {
      "id": "S6",
      "title": "Centrifuge Samples",
      "instruction": "Before injection into the chromatography columns, centrifuge all samples at 16,000 × g for 10 minutes at 4°C."
    },
    {
      "id": "S7",
      "title": "Collect Fractions",
      "instruction": "Collect 0.25 ml fractions during size-exclusion chromatography while monitoring absorbance at 260 and 280 nm."
    },
    {
      "id": "S8",
      "title": "RNA Purification",
      "instruction": "Purify RNA from selected chromatographic peaks using TRIzol LS according to the manufacturer's instructions."
    },
    {
      "id": "S9",
      "title": "Prepare RNA for Sequencing",
      "instruction": "Dilute the purified RNA in 8 μl of ultra-pure RNase-free water and use 7 μl for next-generation sequencing (NGS) library preparation with the NEBNext Small RNA Library Prep Set."
    },
    {
      "id": "S10",
      "title": "Perform Sequencing",
      "instruction": "Sequence the prepared library on a MiSeq benchtop sequencer for 200 cycles."
    },
    {
      "id": "S11",
      "title": "Northern Blotting",
      "instruction": "Perform northern blotting using 10% denaturing gels transferred to positively-charged nylon membranes with digoxigenin-labeled DNA probes and alkaline phosphatase-labeled anti-digoxigenin antibody."
    },
    {
      "id": "S12",
      "title": "Visualize Signals",
      "instruction": "Visualize the signals from the northern blot using CDP-Star and detect them with a ChemiDoc imaging system."
    },
    {
      "id": "S13",
      "title": "Prepare Dendritic Cells",
      "instruction": "Prepare adherent mouse bone marrow-derived dendritic cells (BMDC) as described in the referenced protocol."
    },
    {
      "id": "S14",
      "title": "Add RNA to BMDCs",
      "instruction": "Add selected chromatographic fractions or synthetic RNAs to 1 × 10^6 BMDCs."
    },
    {
      "id": "S15",
      "title": "Flow Cytometry Analysis",
      "instruction": "After 24 hours, harvest the cells and analyze them by flow cytometry using a CyAn ADP Analyzer."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Isolation of T Cells",
      "instruction": "Isolate naive T cells from CBA mice for use in the allogeneic mixed lymphocyte reaction (MLR)."
    },
    {
      "id": "S2",
      "title": "Setup Allogeneic MLR",
      "instruction": "Co-culture isolated naive T cells with B6 BM-DCcons to initiate the allogeneic MLR and stimulate T cell proliferation."
    },
    {
      "id": "S3",
      "title": "Add DCregs to MLR",
      "instruction": "Introduce B6 BM-DCregs and iPS-DCregs into the MLR to assess their inhibitory effects on T cell proliferation."
    },
    {
      "id": "S4",
      "title": "Establish OVA-specific MLR",
      "instruction": "Co-culture T cells from B6-background TCR transgenic mice OT-II and OT-I with OVA-pulsed B6 BM-DCcons for 3 days."
    },
    {
      "id": "S5",
      "title": "Add DCregs to OVA-specific MLR",
      "instruction": "Incorporate B6 BM-DCregs and iPS-DCregs into the OVA-specific MLR to evaluate their regulatory effects on T cell proliferation."
    },
    {
      "id": "S6",
      "title": "Adoptive Transfer of T Cells",
      "instruction": "Transfer 3 × 10^6 OT-II or OT-I T cells into wild-type B6 mice one day prior to the next experimental step."
    },
    {
      "id": "S7",
      "title": "Inject DCs into Recipients",
      "instruction": "Subcutaneously inject OVA-pulsed B6 BM-DCcons combined with iPS-DCregs into the footpads of the recipient mice."
    },
    {
      "id": "S8",
      "title": "Immunization of Mice",
      "instruction": "Immunize CBA mice with B6-derived DCs and isolate spleen cells 7 days post-immunization for further analysis."
    },
    {
      "id": "S9",
      "title": "Flow Cytometry Analysis",
      "instruction": "Perform flow cytometry on isolated spleen cells to assess the population of CD25+ FOXP3+ Tregs."
    },
    {
      "id": "S10",
      "title": "Co-culture T Cells for Secondary Immunization",
      "instruction": "Elute T cells from spleen cells and co-culture them with B6 BM-DCcons or BALB/c BM-DCcons for secondary immunization."
    },
    {
      "id": "S11",
      "title": "Assess T Cell Proliferation",
      "instruction": "Evaluate the proliferation of CD4+ and CD8+ FOXP3− effector T cells after co-culture with B6 BM-DCcons."
    },
    {
      "id": "S12",
      "title": "Intravenous Injection of DCregs",
      "instruction": "Inject 1 × 10^6 B6 iPS-DCregs or other B6-derived DCs into CBA recipients 7 days before heart allograft transplantation."
    },
    {
      "id": "S13",
      "title": "Monitor Allograft Survival",
      "instruction": "Observe and record the survival time of cardiac allografts in treated recipients."
    },
    {
      "id": "S14",
      "title": "Histological Analysis",
      "instruction": "Perform histological examination of allografts to assess lymphocyte infiltration and other pathological changes."
    },
    {
      "id": "S15",
      "title": "Evaluate Cytokine Expression",
      "instruction": "Measure the mRNA expression levels of proinflammatory cytokines and other markers in allografts from treated and control groups."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Plant Acquisition",
      "instruction": "Obtain rooted petunia plantlets (Petunia x hybrida L. lines P720, W115 [cv. MD], Blue Spark, and Blue Ray) from Danziger–Dan Flower Farm."
    },
    {
      "id": "S2",
      "title": "Plant Growth Conditions",
      "instruction": "Grow the plants in a greenhouse under a 25/20°C day/night temperature regime and a 12/12 h light/dark photoperiod, starting the light period at 0800 h."
    },
    {
      "id": "S3",
      "title": "Flower Collection for Headspace Analysis",
      "instruction": "Collect petunia P720 flowers at various developmental stages (3.5 cm buds to 3 days postanthesis) at 1600 h for dynamic headspace analysis."
    },
    {
      "id": "S4",
      "title": "Initiate Headspace Collection",
      "instruction": "For diel floral emissions, collect petunia P720 flowers at anthesis stage and start headspace collection at 0300 h, continuing at 4-hour intervals for 24 hours."
    },
    {
      "id": "S5",
      "title": "Volatile Collection",
      "instruction": "Collect volatiles emitted from three detached flowers per sample using an adsorbent trap containing 200 mg Porapak Type Q polymer."
    },
    {
      "id": "S6",
      "title": "Volatile Elution",
      "instruction": "Elute trapped volatiles using 1.5 ml hexane and add 2 μg isobutylbenzene as an internal standard to each sample."
    },
    {
      "id": "S7",
      "title": "Petal Tissue Collection",
      "instruction": "Collect 150 mg of petal tissues from at least three different flowers and grind in liquid nitrogen for analysis of free volatile compounds."
    },
    {
      "id": "S8",
      "title": "Extraction of Free Volatiles",
      "instruction": "Extract ground petal tissues in 800 μl hexane containing 2 μg isobutylbenzene, incubate for 2 hours with shaking, then centrifuge at 10,000 g for 10 minutes."
    },
    {
      "id": "S9",
      "title": "Extraction of Glycosylated Compounds",
      "instruction": "Grind corolla limb tissue (150 mg) in liquid nitrogen, suspend in 1.2 ml 80% MeOH:DDW, and sonicate for 20 minutes."
    },
    {
      "id": "S10",
      "title": "Centrifugation and Hydrolysis",
      "instruction": "Centrifuge the sonicated samples at 16,000 g for 10 minutes, vacuum-dry the supernatant, and resuspend in 0.9 ml 0.2 M citrate–phosphate buffer, pH 5.4."
    },
    {
      "id": "S11",
      "title": "Enzymatic Hydrolysis",
      "instruction": "Add 150 μl Viscozyme to the resuspended samples and incubate overnight at 37°C to hydrolyze glycosylated compounds."
    },
    {
      "id": "S12",
      "title": "Final Extraction for GC–MS",
      "instruction": "Extract the hydrolyzed samples in 800 μl hexane containing 2 μg isobutylbenzene and prepare for GC–MS analysis."
    },
    {
      "id": "S13",
      "title": "GC–MS Analysis",
      "instruction": "Perform GC–MS analysis using a TRACE GC 2000 and a TRACE DSQ mass spectrometer, following the specified temperature program."
    },
    {
      "id": "S14",
      "title": "Data Analysis",
      "instruction": "Identify compounds based on mass spectra and retention times using the NIST/EPA/NIH Mass Spectral Library and compare with authentic standards."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Synthesis of desthiobiotin derivatives",
      "instruction": "Synthesize TO1-Dtb and TO3-Dtb using TO1-acetate and TO3-acetate along with EZ link amine PEG4 desthiobiotin as precursors."
    },
    {
      "id": "S2",
      "title": "Confirm product identity",
      "instruction": "Confirm the identity of the synthesized products by electrospray ionization–mass spectrometry."
    },
    {
      "id": "S3",
      "title": "Prepare streptavidin agarose beads",
      "instruction": "Wash 400 µL of streptavidin agarose beads twice with Buffer A and three times with Buffer B."
    },
    {
      "id": "S4",
      "title": "Derivatize agarose beads",
      "instruction": "Add 22.5 nmol of TO1-Dtb in 400 µL Buffer B to the washed beads and incubate for 15 minutes at room temperature."
    },
    {
      "id": "S5",
      "title": "Wash beads",
      "instruction": "Wash the beads once with 400 µL Buffer B to remove unbound dye."
    },
    {
      "id": "S6",
      "title": "Prepare yeast strain",
      "instruction": "Transform the U1M gene into the yeast strain yAAH0441 and select transformants on dropout media."
    },
    {
      "id": "S7",
      "title": "Confirm yeast transformants",
      "instruction": "Confirm the presence of the U1-Mango gene and absence of the WT allele by PCR and DNA sequencing."
    },
    {
      "id": "S8",
      "title": "Prepare yeast whole-cell extracts",
      "instruction": "Prepare whole-cell extracts from the yeast strains yAAH1204 and yAAH1362 using the liquid nitrogen method."
    },
    {
      "id": "S9",
      "title": "Label yeast extracts",
      "instruction": "Incubate 500 µL of yeast whole-cell extracts with SNAP-Surface 549 tag and inhibitors at room temperature for 30 minutes."
    },
    {
      "id": "S10",
      "title": "Pull-down snRNPs",
      "instruction": "Add yeast extracts to TO1-Dtb saturated agarose beads and incubate at 4°C for 1 hour."
    },
    {
      "id": "S11",
      "title": "Wash beads",
      "instruction": "Wash the beads twice with Buffer B at 4°C and once more at 30°C."
    },
    {
      "id": "S12",
      "title": "Elute snRNPs",
      "instruction": "Elute the snRNPs by adding Buffer B with 20 mM biotin and incubate at 37°C for 30 minutes."
    },
    {
      "id": "S13",
      "title": "Analyze eluted samples",
      "instruction": "Concentrate part of the biotin eluate for SDS-PAGE analysis and process the remaining for RNA analysis."
    },
    {
      "id": "S14",
      "title": "Perform RT-primer extension",
      "instruction": "Add labeled primers to the precipitated RNA and carry out reverse transcription at 45°C for 1 hour."
    },
    {
      "id": "S15",
      "title": "Load gels for electrophoresis",
      "instruction": "Load the reactions onto denaturing and native polyacrylamide gels for electrophoresis and analyze the results."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Viral RNA Extraction",
      "instruction": "Extract viral RNA from 140 μl of virus culture supernatants or patients' plasma using the QIAamp Viral Min Kit. Elute the RNA in 50 μl of nuclease-free water and store it at -80°C until further use."
    },
    {
      "id": "S2",
      "title": "Obtain DENV-4 3′-UTR Fragment",
      "instruction": "Use the StarScript II Probe One-Step qRT-PCR Kit with primers F3/134 and B3/4 to obtain the 3′-UTR fragment of the DENV-4 genome."
    },
    {
      "id": "S3",
      "title": "Sub-clone 3′-UTR Fragment",
      "instruction": "Sub-clone the obtained 3′-UTR fragment into the pMD18-T plasmid vector."
    },
    {
      "id": "S4",
      "title": "Construct Mutant Viral RNAs",
      "instruction": "Use a fast mutagenesis system to construct various mutants that form mismatches with the F3, FIP, and BLP primers. Confirm the mutants by Sanger sequencing."
    },
    {
      "id": "S5",
      "title": "In vitro Transcription of Mutant RNAs",
      "instruction": "Obtain mutant RNAs through in vitro transcription using T7 RNA polymerase."
    },
    {
      "id": "S6",
      "title": "Quantify Mutant RNAs",
      "instruction": "Quantify the mutant RNAs using spectrophotometric absorbance at 260 nm and calculate the copy number using the provided formula."
    },
    {
      "id": "S7",
      "title": "Prepare RT-LAMP Reaction Mix",
      "instruction": "Prepare a 25 μl reaction mix for the RT-LAMP assay, including all necessary components such as Bst 2.0 DNA polymerase, WarmStart RT, Q5 High-Fidelity DNA polymerase, primers, and RNA."
    },
    {
      "id": "S8",
      "title": "Perform RT-LAMP Reaction",
      "instruction": "Conduct the RT-LAMP reaction at 63°C for 60 minutes, using SYTO 9 as a fluorescent dye for real-time monitoring."
    },
    {
      "id": "S9",
      "title": "Determine Sensitivity and LOD",
      "instruction": "Use ten-fold serial dilutions of RNA from DENV stocks to determine the sensitivity and limit of detection (LOD) of the RT-LAMP assay."
    },
    {
      "id": "S10",
      "title": "Evaluate Clinical Samples",
      "instruction": "Evaluate the performance of the RT-LAMP assay using 153 plasma samples from dengue-suspected patients, comparing results with NS1 antigen detection and RT-PCR assays."
    },
    {
      "id": "S11",
      "title": "Perform RT-Nested PCR for Confirmation",
      "instruction": "For samples with discrepancies between RT-PCR and RT-LAMP results, perform RT-nested PCR using specific outer and inner primers."
    },
    {
      "id": "S12",
      "title": "Visual Detection Method Development",
      "instruction": "Add hydroxynaphthol blue (HNB) to the RT-LAMP reaction mix to develop a visual detection method, and observe color changes at specified time points."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Bacterial Growth",
      "instruction": "Grow Escherichia coli strains NEB5α and BL21(DE3) in LB broth with aeration at 250 rpm until the desired growth is achieved."
    },
    {
      "id": "S2",
      "title": "Plasmid Transformation",
      "instruction": "Transform plasmids into E. coli cells using electroporation and select transformants by plating on LB agar with the appropriate antibiotic."
    },
    {
      "id": "S3",
      "title": "Incubation",
      "instruction": "Incubate the plated transformants at 37°C overnight to allow colonies to form."
    },
    {
      "id": "S4",
      "title": "Plasmid Construction",
      "instruction": "Use CloneAmp HiFi PCR Premix to amplify DNA and insert M. smegmatis DnaBi1 into kanR of pUC4K using Gibson assembly."
    },
    {
      "id": "S5",
      "title": "Plasmid Preparation",
      "instruction": "Prepare plasmids using an E.Z.N.A. plasmid minikit for subsequent experiments."
    },
    {
      "id": "S6",
      "title": "Spot Titer Assay Preparation",
      "instruction": "Grow M. smegmatis in 7H9 and 7H10 media prior to performing spot titer assays."
    },
    {
      "id": "S7",
      "title": "Subcloning",
      "instruction": "Subclone KD154 into the mycobacterial shuttle vector pMBC283 using Gibson assembly for further analysis."
    },
    {
      "id": "S8",
      "title": "Dilution Series",
      "instruction": "Prepare two-fold dilutions of M. smegmatis cells starting from OD600 values of 3 to 5 for spot titer assays."
    },
    {
      "id": "S9",
      "title": "Spotting Cells",
      "instruction": "Spot 1.25 μl of each dilution onto 7H10 media and incubate at 30°C for 5 days."
    },
    {
      "id": "S10",
      "title": "MIG Reporter Expression",
      "instruction": "Express the MIG reporter in BL21(DE3) by subculturing overnight cultures in fresh LB and inducing protein expression at OD600 ∼0.5."
    },
    {
      "id": "S11",
      "title": "Cell Lysis",
      "instruction": "Resuspend cell pellets in MIG buffer and lyse using a tip sonicator on ice."
    },
    {
      "id": "S12",
      "title": "Sample Incubation",
      "instruction": "Incubate the lysate at 16°C for the specified duration for M. smegmatis DnaBi1 and M. leprae DnaB."
    },
    {
      "id": "S13",
      "title": "Zinc Treatment",
      "instruction": "Add zinc acetate to the samples immediately before incubation to assess splicing inhibition."
    },
    {
      "id": "S14",
      "title": "Gel Electrophoresis",
      "instruction": "Separate samples on 8% to 16% Tris-glycine gels and detect GFP-containing products using an imager."
    },
    {
      "id": "S15",
      "title": "Data Analysis",
      "instruction": "Quantify the results using ImageJ and analyze the data with GraphPad Prism."
    }
  ]
}

{
  "steps": [
    {
      "id": "S1",
      "title": "Purification of Antibodies",
      "instruction": "Purify polyclonal ACPA IgGs and non-ACPA control IgGs from pooled serum of RA patients and non-pooled sera of ACPA-positive patients. Purify polyclonal antiproteinase 3 IgGs and non-anti-PR3 control IgGs from the sera of a patient with PR3-associated vasculitis."
    },
    {
      "id": "S2",
      "title": "Quality Control Testing",
      "instruction": "Perform extensive quality control testing on all purified IgGs, including specificity evaluation, size exclusion chromatography aggregation test, and limulus amebocyte lysate (LAL) endotoxin test."
    },
    {
      "id": "S3",
      "title": "Cell Culture Preparation",
      "instruction": "Culture RA-derived and osteoarthritis-derived synovial fibroblasts as well as human dermal fibroblasts for subsequent experiments."
    },
    {
      "id": "S4",
      "title": "Cytokine Treatment",
      "instruction": "Culture fibroblasts in the presence or absence of IL-8 or TNF-α to assess their effects on the cells."
    },
    {
      "id": "S5",
      "title": "Migration Assay",
      "instruction": "Assess fibroblast migration using either the IncuCyte Zoom live cell imaging system or a scratch assay."
    },
    {
      "id": "S6",
      "title": "Adhesion Assay",
      "instruction": "Perform adhesion assays using 16-well E-plates and the xCELLigence System Real-Time Cell Analyzer."
    },
    {
      "id": "S7",
      "title": "Cell Washing and Starvation",
      "instruction": "Wash the cells with phosphate buffered saline and starve them for 2 hours in medium without fetal bovine serum before further treatments."
    },
    {
      "id": "S8",
      "title": "Pretreatment with Proteins",
      "instruction": "Add citrullinated or native human purified fibrinogen, recombinant vimentin, α-enolase, and histone H4 as pretreatment to ACPA and control IgGs at 4°C overnight."
    },
    {
      "id": "S9",
      "title": "Inhibition of Pathways",
      "instruction": "Inhibit PI3K with wortmanin, PTEN with SF-1670, and PAD activity with Cl-amidine or GSK199 for 72 hours prior to scratching."
    },
    {
      "id": "S10",
      "title": "Immunohistochemistry",
      "instruction": "Stain fibroblast-like synoviocytes (FLS) with primary antibodies followed by HRP-conjugated antibodies, develop with Vectastain Elite ABC and DAB, and counterstain with Mayer’s haematoxylin."
    },
    {
      "id": "S11",
      "title": "Confocal Microscopy",
      "instruction": "Incubate cells and tissues with primary and secondary antibodies, then counterstain with 4,6-diamidino-2-phenylindole for confocal microscopy."
    },
    {
      "id": "S12",
      "title": "Mass Spectrometry Analysis",
      "instruction": "Analyze starved and non-starved FLS whole cell lysates by mass spectrometry to detect citrullination."
    },
    {
      "id": "S13",
      "title": "Western Blot Analysis",
      "instruction": "Load cell lysates onto an SDS-PAGE gel, transfer to nitrocellulose membranes, and incubate with primary and peroxidase-conjugated secondary antibodies."
    },
    {
      "id": "S14",
      "title": "Flow Cytometry",
      "instruction": "Collect cells using non-enzymatic detachment reagent, stain with fluorochrome-labelled antibodies, and analyze using a FACSVerse flow cytometer."
    },
    {
      "id": "S15",
      "title": "Statistical Analysis",
      "instruction": "Analyze the data using either the Kruskal-Wallis test followed by Dunn’s multiple comparison test or two-way ANOVA followed by Tukey’s post hoc test using GraphPad Prism 6 software."
    }
  ]
}

