{
  "steps": [
    {
      "id": "S1",
      "title": "Prepare Neuronal Cultures",
      "instruction": "Collect tissue specimens from mouse embryos (E15.5) in dissection media and culture them in neuronal complete medium on 12 mm coverslips in 24-well plates."
    },
    {
      "id": "S2",
      "title": "Plate Neurons",
      "instruction": "Plate high-density neuronal cultures at a density of 750–1000 cells/mm² and allow them to grow."
    },
    {
      "id": "S3",
      "title": "Transduce Neurons",
      "instruction": "Transduce primary neuronal cultures with GFP-expressing pLVTH virus at DIV4 at a multiplicity of infection (MOI) of 2."
    },
    {
      "id": "S4",
      "title": "Treat Neurons",
      "instruction": "Treat neurons with 10 ng/ml FGFb and 5 ng/ml EGF for 10 minutes."
    },
    {
      "id": "S5",
      "title": "Perform MTT Assay",
      "instruction": "Seed cortical cultures in a 96-well plate at 5 × 10³ cells/cm² and incubate for 24 hours at 37°C."
    },
    {
      "id": "S6",
      "title": "Add MTT Solution",
      "instruction": "Solubilize MTT in PBS at 5 mg/ml and add it to the cultures to achieve a final concentration of 0.25 mg/ml, then incubate for 2 hours at 37°C."
    },
    {
      "id": "S7",
      "title": "Measure Absorbance",
      "instruction": "Decant the medium, solubilize formazan precipitates in 200 μL of DMSO, and measure absorbance at 570 nm using a spectrophotometer."
    },
    {
      "id": "S8",
      "title": "Wash Neurons",
      "instruction": "Wash neurons in PBS to prepare for biochemical analysis."
    },
    {
      "id": "S9",
      "title": "Lyse Neurons",
      "instruction": "Lysis neurons in RIPA buffer and agitate gently for 1 hour at 4°C."
    },
    {
      "id": "S10",
      "title": "Centrifuge Lysate",
      "instruction": "Clarify the lysate by centrifugation at 16,000 g for 20 minutes at 4°C."
    },
    {
      "id": "S11",
      "title": "Prepare Protein Samples",
      "instruction": "Measure protein concentration using the Bradford assay and dilute samples with Laemmli buffer for SDS-PAGE."
    },
    {
      "id": "S12",
      "title": "Transfer Proteins",
      "instruction": "Load protein samples onto 10% SDS-PAGE gels and transfer proteins to nitrocellulose membranes."
    },
    {
      "id": "S13",
      "title": "Apply Primary Antibodies",
      "instruction": "Incubate membranes with primary antibodies overnight in blocking buffer."
    },
    {
      "id": "S14",
      "title": "Detect Proteins",
      "instruction": "Use the ECL prime detection system to visualize proteins and acquire images using the ChemiDoc Touch imaging system."
    },
    {
      "id": "S15",
      "title": "Analyze Data",
      "instruction": "Quantify protein bands using ImageLab software and log data for statistical analysis."
    }
  ]
}
